window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[348]={"id":"348","numero":348,"titre":"Insuffisance rénale aiguë","objectifs":[{"id":"348-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d'une insuffisance rénale aiguë (IRA) et de sa sévérité (oligurie, anurie) chez l'adulte et l'enfant","contenu":"<p>L'<span class=\"kw-def\"><strong>IRA</strong></span> se définit par une <span class=\"kw-clinique\">altération rapide de la fonction rénale glomérulaire</span>. Sa reconnaissance et sa <span class=\"kw-def\">classification</span> reposent sur <strong>deux paramètres</strong> : l'élévation de la <span class=\"kw-bio\">créatinine plasmatique</span> et le volume de la <span class=\"kw-clinique\">diurèse</span>.</p>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-bio\">Créatininémie</span> de référence.</strong> On prend comme base la <span class=\"kw-bio\">créatininémie connue la plus récente</span>. En cas de doute sur le caractère aigu ou chronique, il est <strong>préférable de considérer l'<span class=\"kw-ci\">insuffisance rénale</span> comme aiguë</strong>.</div>\n      <p><strong><span class=\"kw-def\">Classification</span> en stades (<span class=\"kw-bio\">créatinine</span> + diurèse)</strong></p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th><span class=\"kw-bio\">Créatininémie</span></th><th>Diurèse</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-chiffre\"><strong>Stade 1</strong></span></td>\n            <td>augmentation <span class=\"kw-chiffre\">&gt; 26 µmol/L</span> en <span class=\"kw-chiffre\">48 h</span>, ou <span class=\"kw-chiffre\">&gt; 50 %</span> en <span class=\"kw-chiffre\">7 jours</span></td>\n            <td><span class=\"kw-chiffre\">&lt; 0,5 mL/kg/h</span> pendant <span class=\"kw-chiffre\">6-12 h</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-chiffre\"><strong>Stade 2</strong></span></td>\n            <td><span class=\"kw-bio\">créatininémie</span> <span class=\"kw-chiffre\">× 2</span> en <span class=\"kw-chiffre\">7 jours</span></td>\n            <td><span class=\"kw-chiffre\">&lt; 0,5 mL/kg/h</span> pendant <span class=\"kw-chiffre\">≥ 12 h</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Stade 3</strong></span></td>\n            <td><span class=\"kw-bio\">créatininémie</span> <span class=\"kw-chiffre\">× 3</span> en <span class=\"kw-chiffre\">7 jours</span>, ou <span class=\"kw-chiffre\">&gt; 354 µmol/L</span>, ou <span class=\"kw-alerte\">nécessité de dialyse</span></td>\n            <td><span class=\"kw-chiffre\">&lt; 0,3 mL/kg/h</span> pendant <span class=\"kw-chiffre\">≥ 24 h</span>, ou <span class=\"kw-alerte\">anurie</span> pendant <span class=\"kw-chiffre\">≥ 12 h</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Sévérité — oligurie et anurie</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\"><strong>Oligurie</strong></span> : diurèse <span class=\"kw-chiffre\">&lt; 0,5 mL/kg/h</span></li>\n        <li><span class=\"kw-alerte\"><strong>Anurie</strong></span> : <span class=\"kw-chiffre\">&lt; 100-200 mL/24 h</span> avec vessie vide</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Piège physiologique.</strong> En IRA, la fonction rénale est <span class=\"kw-alerte\">instable</span> : il <strong>n'est pas possible d'estimer le <span class=\"kw-bio\">DFG</span></strong> (la <span class=\"kw-bio\">créatinine</span> est un marqueur indirect et retardé). On raisonne sur la <span class=\"kw-bio\">cinétique de la créatinine</span> + la <span class=\"kw-clinique\">diurèse</span>, pas sur un <span class=\"kw-bio\">DFG</span> estimé.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 258 — Élévation de la <span class=\"kw-bio\">créatininémie</span> · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":2},{"id":"348-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principaux types et les mécanismes d'insuffisance rénale aiguë","contenu":"<p>Le débit de filtration glomérulaire (<span class=\"kw-bio\">DFG = Puf × Kf</span>) dépend du <span class=\"kw-bio\">débit plasmatique rénal (DPR)</span>, de la <span class=\"kw-bio\">pression capillaire glomérulaire (Pcg ≈ 45 mmHg)</span>, de la pression dans la chambre urinaire (<span class=\"kw-bio\">Pu ≈ 10 mmHg</span>) et du coefficient de filtration <span class=\"kw-bio\">Kf</span> (perméabilité × surface). L'<span class=\"kw-def\">autorégulation</span> maintient DPR et <span class=\"kw-bio\">DFG</span> constants pour une PAS de <span class=\"kw-chiffre\">80-200 mmHg</span>.</p>\n      <p><strong>Mécanismes généraux de l'IRA</strong> (situations où la filtration baisse ou s'annule) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Diminution du DPR</span> et de la <span class=\"kw-clinique\">Pcg</span> : hypovolémie, <span class=\"kw-alerte\">état de choc</span>, hypoperfusion rénale</li>\n        <li><span class=\"kw-clinique\">Augmentation de la Pu</span> : obstacle intra-tubulaire ou sur la voie excrétrice</li>\n        <li><span class=\"kw-clinique\">Diminution du Kf</span> : <span class=\"kw-ttt\">réduction</span> de la surface capillaire de filtration</li>\n      </ul>\n      <p><strong><span class=\"kw-clinique\">Les</span> <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>rands types d'IRA</strong></p>\n      <table >\n        <thead><tr><th>Type</th><th>Mécanisme</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Fonctionnelle</strong> (pré-rénale)</span></td><td>parenchyme <strong>intact</strong> ; baisse du DPR et de la Pcg ; <span class=\"kw-clinique\">réversible</span> si la perfusion est restaurée</td><td>très fréquente</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Organique</strong> (parenchymateuse)</span></td><td><span class=\"kw-clinique\">lésion</span> du parenchyme : tubule (NTA), interstitium (NIA), glomérule, vaisseaux</td><td>très fréquente</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Obstructive</strong> (post-rénale)</span></td><td>obstacle sur la voie excrétrice → ↑ Pu → annulation de la filtration</td><td>≈<span class=\"kw-chiffre\"> 10 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>IRA fonctionnelle → organique.</strong> Une IRA fonctionnelle est <span class=\"kw-clinique\">immédiatement réversible</span> si le flux sanguin rénal est restauré ; si l'hypoperfusion persiste, elle évolue vers une <span class=\"kw-alerte\">NTA ischémique</span> (devient organique).</div>\n      <p><strong>Profils physiopathologiques de l'IRA organique</strong></p>\n      <table >\n        <thead><tr><th></th><th>NTA</th><th>NIA</th><th>Glomérulaire</th><th>Vasculaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td><span class=\"kw-chiffre\">80 %</span></td><td><span class=\"kw-chiffre\">5 %</span></td><td><span class=\"kw-chiffre\">5 %</span></td><td><span class=\"kw-chiffre\">10 %</span></td></tr>\n          <tr><td><strong>Mécanisme</strong></td><td>↓ Pcg + ↑ Pu (débris)</td><td>↑ Pu (<span class=\"kw-clinique\">œdème</span> interstitiel)</td><td>↓ Kf (surface)</td><td>↓ Pcg</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">HTA</span></strong></td><td>non (IRA « nue »)</td><td>non</td><td>oui</td><td><span class=\"kw-alerte\">au 1er plan</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Œdèmes</span></strong></td><td>non</td><td>non</td><td>oui</td><td>non</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Protéinurie</span></strong></td><td>tubulaire &lt;<span class=\"kw-chiffre\"> 1 g</span>/j</td><td>tubulaire &lt;<span class=\"kw-chiffre\"> 1 g</span>/j</td><td>glomérulaire &gt;<span class=\"kw-chiffre\"> 1 g</span>/j (<span class=\"kw-chiffre\">≥ 60 %</span> <span class=\"kw-bio\">albumine</span>)</td><td>variable</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Hématurie</span></strong></td><td>non</td><td>possible</td><td>constante (GR déformés, cylindres)</td><td>non</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 259 — <span class=\"kw-bio\">Protéinurie</span> et <span class=\"kw-clinique\">syndrome néphrotique</span> · 261 — Néphropathies glomérulaires</em></p>","frequence":8},{"id":"348-3","rang":"B","rubrique":"Épidémiologie","titre":"Connaître la prévalence de l'IRA","contenu":"<p>L'IRA est <span class=\"kw-clinique\">très fréquente</span>, et son <span class=\"kw-def\">incidence</span> est en <span class=\"kw-clinique\">constante augmentation</span> depuis <span class=\"kw-chiffre\">10 ans</span>.</p>\n      <ul>\n        <li>Présente chez <span class=\"kw-chiffre\">25 %</span> des patients hospitalisés (<span class=\"kw-chiffre\">5 %</span> à l'hôpital, <span class=\"kw-chiffre\">1/3</span> en <span class=\"kw-alerte\">réanimation</span>)</li>\n        <li>Concerne <span class=\"kw-chiffre\">4 millions</span> de Français / an</li>\n        <li><span class=\"kw-def\">Prévalence</span> en ambulatoire mal connue mais également très fréquente</li>\n      </ul>\n      <p><strong>Terrains à risque</strong></p>\n      <ul>\n        <li>Patients <span class=\"kw-chiffre\">&gt; 65 ans</span></li>\n        <li><span class=\"kw-def\">Comorbidités</span> : cardiovasculaire, <span class=\"kw-etio\">diabète</span>, hépatopathie, maladie rénale préexistante</li>\n        <li>États septiques : <span class=\"kw-alerte\">1ʳᵉ cause d'IRA en réanimation</span> (<span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">50 %</span> en cas de <span class=\"kw-alerte\">choc septique</span>)</li>\n      </ul>\n      <p><strong>Répartition des causes en milieu hospitalier</strong></p>\n      <table >\n        <thead><tr><th>Cause</th><th>Part</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">NTA</span> (<span class=\"kw-clinique\">nécrose</span> tubulaire aiguë)</td><td><span class=\"kw-chiffre\">45 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">IRA fonctionnelle</span></td><td><span class=\"kw-chiffre\">20 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">IRA sur IRC</span></td><td><span class=\"kw-chiffre\">13 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">IRA obstructive</span></td><td><span class=\"kw-chiffre\">10 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">NTIA</span> (néphrite tubulo-interstitielle aiguë)</td><td><span class=\"kw-chiffre\">1,6 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">IRA vasculaire</span></td><td><span class=\"kw-chiffre\">1 %</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"348-4","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription et d'interprétation des résultats des examens complémentaires utiles au diagnostic d'IRA","contenu":"<p>La démarche est hiérarchisée : éliminer une <span class=\"kw-alerte\">urgence</span>, dater l'IRA, écarter un obstacle, puis caractériser le mécanisme.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Action</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\"><strong>1</strong></span></td><td>Éliminer <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">indications de dialyse en urgence</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\"><strong>2</strong></span></td><td>Préciser le caractère <span class=\"kw-clinique\">aigu (IRA)</span> ou <span class=\"kw-clinique\">chronique (IRC)</span> ; si doute → considérer comme aiguë</td></tr>\n          <tr><td><span class=\"kw-chiffre\"><strong>3</strong></span></td><td><span class=\"kw-imagerie\">Échographie de l'appareil urinaire</span> : écarter d'abord un <span class=\"kw-etio\">obstacle</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\"><strong>4</strong></span></td><td><span class=\"kw-bio\">Iono sang + urinaire</span>, <span class=\"kw-bio\">urée</span> et <span class=\"kw-bio\">créatinine</span> plasmatiques + urinaires : évoquer une <span class=\"kw-etio\">IRA fonctionnelle</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\"><strong>5</strong></span></td><td>Par défaut, <span class=\"kw-etio\">IRA organique</span> → diagnostic syndromique (<span class=\"kw-chiffre\">NTA dans 80 %</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Indices urinaires : IRA fonctionnelle <span class=\"kw-bio\">vs</span> NTA</strong></p>\n      <table >\n        <thead><tr><th>Signe</th><th>IRA fonctionnelle</th><th>NTA</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Urée</span> / <span class=\"kw-bio\">créatinine</span> plasmatique (µmol/L)</td><td><span class=\"kw-chiffre\">&gt; 100</span></td><td><span class=\"kw-chiffre\">&lt; 50</span></td></tr>\n          <tr><td>Na⁺ urinaire</td><td><span class=\"kw-chiffre\">&lt; 20 mmol/L</span> (si pas de <span class=\"kw-ttt\">diurétique</span>)</td><td><span class=\"kw-chiffre\">&gt; 40 mmol/L</span></td></tr>\n          <tr><td>FE Na⁺</td><td><span class=\"kw-chiffre\">&lt; 1 %</span></td><td><span class=\"kw-chiffre\">&gt; 1-2 %</span></td></tr>\n          <tr><td>FE <span class=\"kw-bio\">urée</span> (utile si <span class=\"kw-ttt\">diurétiques</span>)</td><td><span class=\"kw-chiffre\">&lt; 35 %</span></td><td><span class=\"kw-chiffre\">&gt; 35-40 %</span></td></tr>\n          <tr><td>Na⁺/K⁺ urinaire</td><td><span class=\"kw-chiffre\">&lt; 1</span> (inversé)</td><td><span class=\"kw-chiffre\">&gt; 1</span></td></tr>\n          <tr><td>U/P osmoles · U/P <span class=\"kw-bio\">urée</span> · U/P <span class=\"kw-bio\">créatinine</span></td><td>&gt; 2 · &gt; 10 · &gt; 30</td><td>&lt; 2 · &lt; 10 · &lt; 30</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Pièges d'interprétation.</strong> Exprimer la <span class=\"kw-bio\">créatinine urinaire en µmol/L</span> (× 1000) avant le rapport. Sous <span class=\"kw-ttt\">diurétique</span> ou en cas de perte rénale de Na⁺, la FE Na est faussée → utiliser la <strong>FE <span class=\"kw-bio\">urée</span></strong>. À l'inverse, la natriurèse peut être basse dans certaines NTA (rhabdomyolyse, PDC iodés).</div>\n      <p><strong>Diagnostic syndromique de l'IRA organique</strong> — orienté par <span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">hématurie</span>, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-clinique\">œdèmes</span> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">NTA</span> : IRA « nue », <span class=\"kw-bio\">protéinurie</span> tubulaire &lt;<span class=\"kw-chiffre\"> 1 g</span>/j</li>\n        <li><span class=\"kw-etio\">NIA</span> : <span class=\"kw-bio\">leucocyturie</span> possible, <span class=\"kw-bio\">éosinophilurie</span> (immuno-<span class=\"kw-etio\">allergique</span>)</li>\n        <li><span class=\"kw-etio\">Glomérulaire</span> : <span class=\"kw-bio\">protéinurie</span> &gt;<span class=\"kw-chiffre\"> 1 g</span>/j, <span class=\"kw-bio\">hématurie</span> (GR déformés/cylindres), <span class=\"kw-etio\">HTA</span>, <span class=\"kw-clinique\">œdèmes</span></li>\n        <li><span class=\"kw-etio\">Vasculaire</span> : <span class=\"kw-etio\">HTA</span> au 1er plan</li>\n      </ul>\n      <p><strong><span class=\"kw-ttt\">Ponction</span>-<span class=\"kw-ttt\">biopsie</span> rénale (PBR)</strong> — indications : tableau de NTA sans circonstances évidentes, signes faisant évoquer une néphropathie <span class=\"kw-clinique\">glomérulaire / vasculaire / interstitielle</span>, ou fonction rénale ne s'améliorant pas <span class=\"kw-chiffre\">3-4 semaines</span> après le début. Précautions : contrôle <span class=\"kw-etio\">HTA</span>, hémostase, repérage échographique.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 258 — Élévation de la <span class=\"kw-bio\">créatininémie</span> · 261 — Néphropathies glomérulaires</em></p>","frequence":16},{"id":"348-5","rang":"B","rubrique":"Identifier une urgence","titre":"Connaître les situations nécessitant un avis spécialisé dans l'IRA","contenu":"<p>Au-delà des urgences vitales imposant la dialyse, plusieurs situations imposent le recours au <span class=\"kw-clinique\">néphrologue</span> (ou à l'<span class=\"kw-clinique\">urologue</span>) car elles modifient la prise en charge.</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Indication potentielle d'épuration extra-rénale</span> (hyperkaliémie / acidose / surcharge menaçantes — <em>cf. objectif dédié</em>)</li>\n        <li>Suspicion d'<span class=\"kw-etio\">IRA organique non-NTA</span> : signes glomérulaires (<span class=\"kw-bio\">protéinurie</span> &gt;<span class=\"kw-chiffre\"> 1 g</span>/j, <span class=\"kw-bio\">hématurie</span>, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-clinique\">œdèmes</span>) ou vasculaires → discuter une <span class=\"kw-imagerie\">PBR</span></li>\n        <li>Suspicion de <span class=\"kw-alerte\">glomérulonéphrite rapidement progressive</span> ou de <span class=\"kw-alerte\">vascularite</span> (<span class=\"kw-alerte\">urgence</span> diagnostique et thérapeutique)</li>\n        <li><span class=\"kw-etio\">IRA obstructive</span> confirmée → avis <span class=\"kw-clinique\">urologique</span> pour dérivation des urines</li>\n        <li><span class=\"kw-clinique\">Doute aigu / chronique</span> persistant, ou IRA sur IRC évoluée</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Réflexe.</strong> Une IRA qui n'est ni clairement fonctionnelle (réversible au remplissage) ni clairement obstructive (levée d'obstacle) relève d'un <span class=\"kw-clinique\">avis néphrologique</span> — surtout devant des signes extra-rénaux orientant vers une maladie systémique.</div>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « signes imposant une PEC urgente en milieu spécialisé » · objectif « indications de la dialyse en <span class=\"kw-alerte\">urgence</span> »</em></p>","frequence":1},{"id":"348-6","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies d'IRA par obstacle","contenu":"<p>Pour entraîner une IRA, l'obstacle doit être <span class=\"kw-alerte\">bilatéral</span> (ou sur <span class=\"kw-alerte\">rein unique</span> anatomique ou fonctionnel). L'orientation dépend de l'âge et de la localisation.</p>\n      <div class=\"callout callout-info\"><strong>Selon l'âge.</strong> Sujet <span class=\"kw-clinique\">jeune</span> → obstacle <span class=\"kw-etio\">lithiasique</span> (oxalo-calcique le plus souvent ; migration bilatérale exceptionnelle, IRA surtout si rein unique). Sujet <span class=\"kw-clinique\">âgé</span> → prédominance des causes <span class=\"kw-etio\">tumorales</span>.</div>\n      <p><strong>Selon la localisation</strong></p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Sous-vésical / intra-vésical</strong></span></td>\n            <td><span class=\"kw-etio\">adénome de prostate (HBP)</span>, cancer de prostate, <span class=\"kw-clinique\">prostatite</span> ; maladie du col vésical ; sténose de l'urètre ; phimosis serré ; <span class=\"kw-etio\">valves de l'urètre postérieur</span> (enfant) ; vessie neurologique ; caillotage, tumeur de vessie, calcul vésical ; prolapsus / tumeur pelvienne (femme)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Urétéral — intraluminal</strong></span></td>\n            <td><span class=\"kw-etio\">lithiase urinaire</span> ; <span class=\"kw-clinique\">nécrose</span> papillaire aiguë</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Urétéral — pariétal</strong></span></td>\n            <td>tumeur urothéliale ; <span class=\"kw-etio\">tuberculose</span> urogénitale ; sténose radique ; endométriose ; <span class=\"kw-clinique\">syndrome de la</span> jonction pyélo-urétérale</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Urétéral — extrapariétal</strong></span></td>\n            <td>tumeur pelvienne localement avancée (prostate, col utérin, rectum, ovaire) ; <span class=\"kw-etio\">fibrose / liposclérose rétropéritonéale</span> ; <span class=\"kw-clinique\">adénopathies</span> lombo-aortiques ; métastases rétropéritonéales</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 265 — Lithiase urinaire · 310 — Tumeurs de la prostate · 314 — Tumeurs vésicales</em></p>","frequence":2},{"id":"348-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies d'IRA fonctionnelle","contenu":"<p>Le parenchyme est <span class=\"kw-clinique\">intact</span> : il s'agit d'une <span class=\"kw-def\">hypoperfusion rénale</span> (baisse du DPR et de la Pcg), <strong>réversible</strong> si la perfusion est rétablie.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Hypovolémie vraie</strong></span></td><td><span class=\"kw-clinique\">hémorragie</span> ; <span class=\"kw-clinique\">déshydratation extra-cellulaire</span> (pertes digestives, rénales, cutanées)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Hypovolémie efficace</strong></span></td><td><span class=\"kw-clinique\">insuffisance cardiaque</span> ; <span class=\"kw-clinique\">insuffisance hépatique</span> (cirrhose) ; <span class=\"kw-alerte\">sepsis</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>IRA hémodynamique médicamenteuse</strong></span></td><td>anti-calcineurines ; <span class=\"kw-ttt\">IEC / ARA2</span> (vasodilatation de l'artériole <strong>efférente</strong>) ; <span class=\"kw-ttt\">AINS</span> (vasoconstriction de l'artériole <strong>afférente</strong>) ; <span class=\"kw-ttt\">diurétiques</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Médicaments « hémodynamiques ».</strong> <span class=\"kw-ttt\">IEC</span>/<span class=\"kw-ttt\">ARA2</span> et <span class=\"kw-ttt\">AINS</span> ne sont <span class=\"kw-clinique\">pas néphrotoxiques</span> : ils dérèglent l'autorégulation. <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">IEC</span>/<span class=\"kw-ttt\">ARA2</span> lèvent la vasoconstriction de l'efférente, les <span class=\"kw-ttt\">AINS</span> lèvent la vasodilatation (prostaglandines) de l'afférente. Risque majoré en cas de <span class=\"kw-clinique\">déshydratation</span> ou de sténose des artères rénales.</div>\n      <p><strong>Conséquences clinico-biologiques</strong> : oligurie, <span class=\"kw-bio\">urée</span> plasmatique augmentée &gt; <span class=\"kw-bio\">créatinine</span> (réabsorption passive), urines pauvres en Na⁺, riches en K⁺, acides et concentrées (hyperaldostéronisme secondaire).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 257 — <span class=\"kw-clinique\">Œdèmes</span> des membres inférieurs · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span></em></p>","frequence":2},{"id":"348-8","rang":"B","rubrique":"Étiologies","titre":"Connaître les causes d'IRA par nécrose tubulaire aiguë","contenu":"<p>La <span class=\"kw-etio\">NTA</span> est la <strong>1ʳᵉ cause d'IRA organique</strong> (≈<span class=\"kw-chiffre\"> 80 %</span>). Deux grands mécanismes : <span class=\"kw-etio\">ischémique</span> et <span class=\"kw-etio\">toxique</span>.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>NTA ischémique</strong></span></td><td><span class=\"kw-alerte\">état de choc</span> (septique, hypovolémique, cardiogénique), hypoperfusion rénale prolongée (= IRA fonctionnelle non corrigée)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>NTA toxique</strong></span></td><td><span class=\"kw-ttt\">produits de contraste iodés</span> ; <span class=\"kw-ttt\">médicaments néphrotoxiques</span> ; <span class=\"kw-etio\">lyse cellulaire</span> (rhabdomyolyse, <span class=\"kw-clinique\">syndrome de lyse</span> <span class=\"kw-etio\">tumorale</span>, hémolyse) ; <span class=\"kw-etio\">tubulopathie myélomateuse</span> (EPS si &gt;<span class=\"kw-chiffre\"> 50 ans</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Médicaments responsables de NTA</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Aminosides</span>, <span class=\"kw-ttt\">vancomycine</span></li>\n        <li><span class=\"kw-ttt\">Amphotéricine B</span></li>\n        <li><span class=\"kw-ttt\">Produits de contraste iodés</span></li>\n        <li><span class=\"kw-ttt\">Sels de platine</span> (cisplatine, carboplatine)</li>\n        <li><span class=\"kw-ttt\">Ciclosporine A</span>, <span class=\"kw-ttt\">tacrolimus</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Pronostic</span>.</strong> La fonction rénale revient typiquement à l'état antérieur après <span class=\"kw-chiffre\">1 à 3 semaines</span> (régénération de l'épithélium tubulaire à partir des cellules survivantes), mais une séquelle (IRC) reste possible.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — IRC · 332 — États de <span class=\"kw-alerte\">choc</span></em></p>","frequence":2},{"id":"348-9","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales étiologies d'IRA glomérulaires incluant les vascularites","contenu":"<p>L'IRA glomérulaire (≈<span class=\"kw-chiffre\"> 5 %</span>) associe un <span class=\"kw-etio\">syndrome glomérulaire</span> : <span class=\"kw-bio\">protéinurie</span> <span class=\"kw-chiffre\">&gt; 1 g/j</span> (<span class=\"kw-chiffre\">≥ 60 %</span> <span class=\"kw-bio\">albumine</span>), <span class=\"kw-bio\">hématurie</span> (GR déformés, cylindres hématiques), <span class=\"kw-etio\">HTA</span> et <span class=\"kw-clinique\">œdèmes</span>.</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>GNA post-infectieuse</strong></span></td><td>post-streptococcique typiquement ; intervalle libre, hypocomplémentémie</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>GNRP</strong></span> (rapidement progressive)</td><td><span class=\"kw-alerte\">urgence</span> ; à croissants ; types 1 (anti-MBG, <span class=\"kw-etio\">Goodpasture</span>), 2 (complexes immuns), 3 (pauci-immune à <span class=\"kw-bio\">ANCA</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Vascularites à ANCA</strong></span></td><td><span class=\"kw-etio\">GPA</span>, <span class=\"kw-etio\">MPA</span> → GNRP pauci-immune ; syndrome pneumo-rénal possible</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Néphropathie lupique</strong></span></td><td>GN membrano-proliférative ; contexte de <span class=\"kw-clinique\">lupus</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-alerte\">Urgence</span> néphrologique.</strong> Une IRA avec <span class=\"kw-bio\">protéinurie</span> + <span class=\"kw-bio\">hématurie</span> (<span class=\"kw-clinique\">syndrome de glomérulonéphrite</span> aiguë / GNRP) impose un avis néphrologique <strong>rapide</strong> et la discussion d'une <span class=\"kw-imagerie\">PBR</span> : le retard de traitement compromet la récupération rénale.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 261 — Néphropathies glomérulaires · 193 — <span class=\"kw-clinique\">Lupus</span> / vascularites</em></p>","frequence":2},{"id":"348-10","rang":"B","rubrique":"Étiologies","titre":"Connaître les causes d'IRA liée à une atteinte tubulo-interstitielle aiguë","contenu":"<p>La <span class=\"kw-etio\">néphrite interstitielle aiguë (NIA)</span> (≈<span class=\"kw-chiffre\"> 5 %</span>) procède d'un <span class=\"kw-clinique\">œdème interstitiel</span> (↑ Pu). <span class=\"kw-bio\">Leucocyturie</span> possible ; l'<span class=\"kw-bio\">éosinophilurie</span> est évocatrice de la forme immuno-<span class=\"kw-etio\">allergique</span>.</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Infectieuse</strong></span></td><td><span class=\"kw-etio\">PNA bilatérale</span> ++</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Médicamenteuse</strong></span></td><td>NIA <span class=\"kw-etio\">toxique</span> ou <span class=\"kw-clinique\">immuno-allergique</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Infiltration tumorale</strong></span></td><td>lymphome</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Médicaments en cause</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">β-lactamines</span>, <span class=\"kw-ttt\">sulfamides</span>, <span class=\"kw-ttt\">fluoroquinolones</span>, <span class=\"kw-ttt\">rifampicine</span></li>\n        <li><span class=\"kw-ttt\">AINS</span></li>\n        <li><span class=\"kw-ttt\">IPP</span></li>\n        <li><span class=\"kw-ttt\">Immunothérapies anticancéreuses</span> (inhibiteurs de checkpoints)</li>\n        <li><span class=\"kw-ttt\">AVK</span> (<span class=\"kw-ttt\">fluindione</span>)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Signe d'orientation.</strong> L'<span class=\"kw-bio\">éosinophilurie</span> est considérée comme pathognomonique de la <span class=\"kw-clinique\">NIA immuno-allergique</span> ; elle s'inscrit souvent dans un contexte d'introduction médicamenteuse récente (± rash, <span class=\"kw-clinique\">fièvre</span>, hyperéosinophilie).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — Infections urinaires · 264 — IRC</em></p>","frequence":1},{"id":"348-11","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales causes d'IRA vasculaires","contenu":"<p>L'IRA vasculaire (≈<span class=\"kw-chiffre\"> 10 %</span>) résulte d'une baisse de la Pcg par atteinte des vaisseaux rénaux. L'<span class=\"kw-alerte\">HTA est au premier plan</span>.</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Contexte</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Néphroangiosclérose maligne</strong></span></td><td><span class=\"kw-etio\">HTA</span> maligne</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Microangiopathie thrombotique (MAT)</strong></span></td><td>anémie hémolytique mécanique + thrombopénie</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Thrombose aiguë</strong></span></td><td>PAN, SAPL</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Emboles de cholestérol</strong></span></td><td>après geste endovasculaire / <span class=\"kw-ttt\">anticoagulation</span>, <span class=\"kw-def\">terrain</span> <span class=\"kw-etio\">athéromateux</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Crise rénale sclérodermique</strong></span></td><td><span class=\"kw-clinique\">sclérodermie</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Causes médicamenteuses de MAT</strong> : <span class=\"kw-ttt\">inhibiteurs du VEGF</span> (bévacizumab), <span class=\"kw-ttt\">gemcitabine</span>, <span class=\"kw-ttt\">mitomycine C</span>, <span class=\"kw-ttt\">ciclosporine</span>, <span class=\"kw-ttt\">tacrolimus</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 193 — Maladies systémiques · 264 — IRC</em></p>","frequence":1},{"id":"348-12","rang":"A","rubrique":"Étiologies","titre":"Connaître les principaux médicaments ou produits responsables d'IRA","contenu":"<p>Réflexe devant toute IRA : <strong>revoir l'ordonnance</strong>. <span class=\"kw-clinique\">Les</span> médicaments agissent par des mécanismes distincts qu'il faut savoir rattacher.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Principaux médicaments</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>IRA fonctionnelle</strong></span> (hypoperfusion)</td><td><span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-ttt\">IEC / ARA2</span>, <span class=\"kw-ttt\">AINS</span>, anti-calcineurines (<span class=\"kw-ttt\">ciclosporine</span>, <span class=\"kw-ttt\">tacrolimus</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>NTA — toxicité tubulaire directe</strong></span></td><td><span class=\"kw-ttt\">aminosides</span>, <span class=\"kw-ttt\">produits de contraste iodés</span>, <span class=\"kw-ttt\">cisplatine</span>, ifosfamide, immunoglobulines IV</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>NTA — toxicité indirecte</strong></span></td><td>rhabdomyolyse (<span class=\"kw-ttt\">statines</span>, <span class=\"kw-ttt\">fibrates</span>) ; hémolyse (quinine, <span class=\"kw-ttt\">rifampicine</span>) ; cristallurie (<span class=\"kw-ttt\">aciclovir</span>, foscarnet, indinavir, <span class=\"kw-ttt\">méthotrexate</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>NIA allergique</strong></span></td><td><span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">β-lactamines</span>, <span class=\"kw-ttt\">allopurinol</span>, <span class=\"kw-ttt\">IPP</span>, <span class=\"kw-ttt\">AVK</span>, <span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-ttt\">rifampicine</span>, <span class=\"kw-ttt\">ciprofloxacine</span>, cimétidine</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Atteinte glomérulaire</strong></span></td><td><span class=\"kw-ttt\">AINS</span>, interféron, D-pénicillamine</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>MAT</strong></span></td><td><span class=\"kw-ttt\">ciclosporine</span>, gemcitabine, <span class=\"kw-ttt\">clopidogrel</span>, mitomycine</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Toxicité tubulo-interstitielle chronique</strong></span></td><td><span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">antalgiques</span>, anti-calcineurines, ténofovir</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Fibrose rétropéritonéale</strong></span></td><td>ergotamine, β-bloquants</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Prévention.</strong> Adapter la posologie des néphrotoxiques à la fonction rénale, corriger toute hypovolémie, et <strong>arrêter <span class=\"kw-clinique\">les</span> médicaments à risque</strong> (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">IEC</span>/<span class=\"kw-ttt\">ARA2</span>, <span class=\"kw-ttt\">diurétiques</span>) en situation d'hypoperfusion. Les <span class=\"kw-ttt\">AINS</span> sont <span class=\"kw-ci\">contre-indiqués</span> en cas d'IRC et ne doivent pas être associés à un bloqueur du SRAA.</div>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « adaptation de la prescription à la sévérité de l'IR »</em></p>","frequence":3},{"id":"348-13","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes d'IRA chez l'enfant (SHU, déshydratation, choc...) et les mesures hygiéno-diététiques de prévention des SHU","contenu":"<p>Chez l'enfant, l'étiologie varie selon le mécanisme.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Causes pédiatriques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Fonctionnelle</strong> (pré-rénale)</span></td><td><span class=\"kw-clinique\">déshydratation aiguë</span> (GEA, pertes digestives), <span class=\"kw-clinique\">syndrome néphrotique</span>, brûlures, hémorragie ; <span class=\"kw-alerte\">états de choc</span> (septique, cardiogénique) ; <span class=\"kw-ttt\">AINS / IEC</span> surtout en contexte de <span class=\"kw-clinique\">déshydratation</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Organique</strong> (parenchymateuse)</span></td><td><span class=\"kw-etio\">SHU</span> = 1ʳᵉ cause d'IRA organique chez l'enfant de <span class=\"kw-chiffre\">&lt; 3 ans</span> ; NTA (<span class=\"kw-alerte\">choc</span> / ischémie) ; glomérulonéphrites (post-infectieuse, rapidement progressive)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Obstructive</strong> (post-rénale)</span></td><td>uropathies malformatives (ex. <span class=\"kw-etio\">valves de l'urètre postérieur</span>), lithiases, tumeurs</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>SHU typique.</strong> <span class=\"kw-etio\">Microangiopathie thrombotique</span> associant la triade : <span class=\"kw-alerte\">anémie hémolytique mécanique + thrombopénie + IRA</span>. Cause : <span class=\"kw-etio\">toxi-infection alimentaire à <em>E. coli</em> producteur de Shigatoxines (STEC)</span>, souvent après une <span class=\"kw-clinique\">diarrhée</span> (parfois sanglante).</div>\n      <p><strong>Mesures de prévention du SHU</strong> (cruciales avant <span class=\"kw-chiffre\">3 ans</span>) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Cuisson des viandes</span> : bien cuire le bœuf, surtout haché (à cœur, pas de viande rosée)</li>\n        <li><span class=\"kw-clinique\">Produits laitiers</span> : éviter fromages au lait cru et lait non pasteurisé</li>\n        <li><span class=\"kw-clinique\">Végétaux</span> : lavage soigneux des fruits, légumes et herbes (surtout crus)</li>\n        <li><span class=\"kw-clinique\">Hygiène</span> : lavage des mains (avant repas, après toilettes/change) ; nettoyer ustensiles et plans de travail ayant touché de la viande crue</li>\n        <li><span class=\"kw-clinique\">Environnement</span> : éviter le <span class=\"kw-def\">contact</span> direct avec bovins/ovins et leur environnement</li>\n        <li><span class=\"kw-clinique\">Comportement</span> : éviter la baignade en lieu public en cas de <span class=\"kw-clinique\">diarrhée</span> de l'enfant</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 286 — <span class=\"kw-clinique\">Diarrhée</span> aiguë / <span class=\"kw-clinique\">déshydratation</span> du nourrisson · 176 — <span class=\"kw-clinique\">Diarrhée</span> infectieuse</em></p>","frequence":6},{"id":"348-14","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes cliniques et biologiques imposant une prise en charge urgente en milieu spécialisé d'une IRA","contenu":"<p>Quatre complications métaboliques peuvent menacer le <span class=\"kw-alerte\">pronostic vital</span> et imposent une prise en charge spécialisée immédiate.</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Éléments clés</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\"><strong>Hyperkaliémie</strong></span></td><td>baisse de la sécrétion tubulaire de K⁺ (surtout formes anuriques) ; aggravée par anti-aldostérone, <span class=\"kw-ttt\">IEC</span>/<span class=\"kw-ttt\">ARA2</span>, <span class=\"kw-ttt\">triméthoprime</span>-sulfaméthoxazole, et par le relargage cellulaire (acidose, rhabdomyolyse, hémolyse, lyse <span class=\"kw-etio\">tumorale</span>)</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Acidose métabolique</strong></span></td><td>à <span class=\"kw-bio\">trou anionique</span> augmenté ; plus marquée dans <span class=\"kw-clinique\">les</span> IRA obstructives, l'intoxication à l'éthylène glycol, les états de <span class=\"kw-alerte\">choc</span> (acidose lactique), l'acidocétose, les diarrhées</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Surcharge hydro-sodée</strong></span></td><td><span class=\"kw-etio\">HTA</span>, <span class=\"kw-clinique\">œdèmes</span> déclives, épanchements séreux (plèvre, péricarde) voire <span class=\"kw-alerte\">OAP</span></td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Syndrome urémique</strong></span></td><td><span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span>, confusion, <span class=\"kw-clinique\">astérixis</span>, ROT vifs, épilepsie ; si <span class=\"kw-bio\">urée</span> &gt;<span class=\"kw-chiffre\"> 50 mmol/L</span> : <span class=\"kw-alerte\">péricardite, coma, hémorragie digestive</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Bilan à réaliser en <span class=\"kw-alerte\">urgence</span></strong> : examen cardiovasculaire + auscultation pulmonaire ; <span class=\"kw-bio\">ionogramme + bicarbonates plasmatiques</span> ; <span class=\"kw-imagerie\">RXT</span>, <span class=\"kw-bio\">ECG</span>, <span class=\"kw-bio\">gaz du sang</span>.</p>\n      <div class=\"callout callout-danger\"><strong>Indications de dialyse en <span class=\"kw-alerte\">urgence</span>.</strong> <span class=\"kw-alerte\">Hyperkaliémie symptomatique</span> (K⁺ &gt;<span class=\"kw-chiffre\"> 6,5 mmol/L</span> + signes <span class=\"kw-imagerie\">ECG</span>) ; <span class=\"kw-alerte\">acidose métabolique sévère</span> (<span class=\"kw-bio\">pH</span> &lt; 7,20 ; 7,15 en réa) ; <span class=\"kw-alerte\">OAP de surcharge résistant aux diurétiques</span>. La <span class=\"kw-def\">surveillance</span> de la diurèse (sonde à demeure) est justifiée car ces complications surviennent surtout en cas d'anurie.</div>\n      <p><strong>Autres signes biologiques associés</strong> : hypocalcémie secondaire à l'hyperphosphorémie ; risque de dénutrition et d'infections nosocomiales.</p>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectifs « principes / indications de la dialyse »</em></p>","frequence":7},{"id":"348-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités d'adaptation de la prescription des médicaments et des examens complémentaires à la sévérité de l'insuffisance rénale","contenu":"<p>L'<span class=\"kw-ci\">insuffisance rénale</span> modifie la pharmacocinétique : biodisponibilité, volume de distribution, liaison protéique (↑ fraction libre par hypoalbuminémie et toxines urémiques), élimination hépatique et rénale.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Évaluer la fonction rénale</strong></span></td><td>clinique (poids, volume extra-cellulaire) ; estimation du <span class=\"kw-bio\">DFG</span> : <span class=\"kw-bio\">CKD-EPI = référence</span> ; <span class=\"kw-def\">Cockcroft</span> parfois retenue pour l'adaptation des doses (seule formule du <span class=\"kw-def\">RCP</span>) mais mauvaise chez le sujet âgé / en surpoids</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Adapter la dose</strong></span></td><td><span class=\"kw-ttt\">diminuer la dose</span> (index étroit, demi-vie courte) ou <span class=\"kw-ttt\">espacer les prises</span> (demi-vie longue, index large), voire <span class=\"kw-clinique\">les</span> deux</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Cas particulier de l'IRA</strong></span></td><td>pas de moyen simple et fiable de mesurer la fonction rénale (<span class=\"kw-bio\">créatinine</span> = marqueur retardé) → <span class=\"kw-ttt\">monitorage de la concentration plasmatique</span> si disponible</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Prévention de la néphrotoxicité des examens / produits</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Produits de contraste iodés (NPCI)</span> : arrêt <span class=\"kw-ttt\">AINS</span> et <span class=\"kw-ttt\">diurétiques</span>, arrêt <span class=\"kw-ttt\">metformine</span> le jour +<span class=\"kw-chiffre\"> 48 h</span> ; PCI de faible/iso-osmolarité, volume limité ; <span class=\"kw-ttt\">hydratation</span> (NaCl <span class=\"kw-chiffre\">9 ‰</span> ou <span class=\"kw-bio\">bicarbonate</span> <span class=\"kw-chiffre\">1,4 %</span>,<span class=\"kw-chiffre\"> 1 mL</span>/kg/h <span class=\"kw-chiffre\">12 h</span> avant et après)</li>\n        <li><span class=\"kw-ttt\">Néphrotoxiques</span> (aminosides, cisplatine, <span class=\"kw-ttt\">amphotéricine B</span>) : posologie adaptée, dosages résiduels si &gt;<span class=\"kw-chiffre\"> 48 h</span>, hydratation</li>\n        <li><span class=\"kw-ttt\">Syndromes de lyse</span> (rhabdomyolyse, lyse <span class=\"kw-etio\">tumorale</span>) : hydratation abondante, mesures spécifiques</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Attention.</strong> L'altération des fonctions tubulaires n'est <strong>pas proportionnelle</strong> au <span class=\"kw-bio\">DFG</span> estimé : il est hasardeux de prédire le comportement d'un médicament sur la seule estimation du <span class=\"kw-bio\">DFG</span> en contexte d'IRA.</div>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « médicaments responsables d'IRA » · item 330 — Classes médicamenteuses</em></p>","frequence":3},{"id":"348-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement d'une IRA obstructive et la prise en charge d'un syndrome de levée d'obstacle","contenu":"<p>Objectif : <strong>lever l'obstacle immédiatement</strong> pour rétablir l'écoulement des urines. Patient hospitalisé, médicaments néphrotoxiques arrêtés.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\"><strong>D'abord</strong></span></td><td>éliminer une indication de dialyse en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-imagerie\">échographie réno-vésicale</span> ± <span class=\"kw-imagerie\">TDM</span>-AP non injectée</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Globe vésical</strong></span></td><td><span class=\"kw-ttt\">drainage</span> par <span class=\"kw-ttt\">sondage vésical</span> ou <span class=\"kw-ttt\">cathéter sus-pubien</span> (si sondage impossible)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Obstacle haut / anurie</strong></span></td><td>dérivation au-dessus de l'obstacle : <span class=\"kw-ttt\">sonde JJ (urétérale)</span> par voie endoscopique, ou <span class=\"kw-ttt\">néphrostomie percutanée</span> (sous <span class=\"kw-imagerie\">échographie</span> ; risque <span class=\"kw-etio\">hémorragique</span> plus élevé)</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Sepsis</strong></span></td><td><span class=\"kw-ttt\">C3G IV + amikacine</span> après prélèvements (± couverture <span class=\"kw-bio\">EBLSE</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-clinique\">Syndrome de levée</span> d'obstacle.</strong> Après dérivation, <span class=\"kw-clinique\">polyurie massive</span> → risque de <span class=\"kw-clinique\">déshydratation</span> et d'<span class=\"kw-alerte\">hypokaliémie</span>. <strong><span class=\"kw-def\">Surveillance</span></strong> : diurèse horaire, poids, PA, ionogrammes sang/urine répétés. <strong>Compensation</strong> hydro-électrolytique IV « volume pour volume » initialement (NaCl isotonique), puis diminuée progressivement.</div>\n      <p><strong>Complications de la dérivation à surveiller</strong> : hémorragie vésicale <em>a vacuo</em> (prévention par clampage tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">300-500 mL</span> /<span class=\"kw-chiffre\"> 30 min</span>) ; saignement / <span class=\"kw-clinique\">fistule</span> / PNA (néphrostomie). <span class=\"kw-alerte\">UIV et uro-TDM injectés contre-indiqués</span> (PDC iodé <span class=\"kw-ci\">proscrit</span> ici).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 265 — Lithiase urinaire · 161 — Infections urinaires</em></p>","frequence":1},{"id":"348-17","rang":"A","rubrique":"Prise en charge","titre":"Connaître la prise en charge d'une IRA fonctionnelle liée à une déshydratation extra-cellulaire","contenu":"<p>Le traitement vise à <strong>restaurer la volémie</strong> : l'IRA fonctionnelle est réversible si la perfusion rénale est rétablie.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\"><strong>Corriger la DEC</strong></span></td><td>estimation du déficit ; apport sodé : <span class=\"kw-ttt\">sel de table / gélules de NaCl</span> per os, ou <span class=\"kw-ttt\">cristalloïde (NaCl isotonique)</span> IV</td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Arrêter les facteurs aggravants</strong></span></td><td>arrêt des <span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-ttt\">AINS</span>, antihypertenseurs ; <strong>arrêt du régime sans sel</strong></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Surveiller</strong></span></td><td>reprise de la <span class=\"kw-clinique\">diurèse</span> = 1ᵉʳ signe favorable (en quelques heures) ; courbe de poids, FC, PA ; iono urinaire (disparition des signes d'hyperaldostéronisme secondaire)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Bon réflexe.</strong> La remontée de la diurèse dans <span class=\"kw-clinique\">les</span> heures suivant le remplissage signe l'efficacité et confirme rétrospectivement le caractère fonctionnel de l'IRA.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 267 — Troubles de l'équilibre hydro-électrolytique · 257 — <span class=\"kw-clinique\">Œdèmes</span> des MI</em></p>","frequence":3},{"id":"348-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge d'une IRA fonctionnelle liée à une insuffisance cardiaque","contenu":"<p>Il s'agit du <span class=\"kw-etio\">syndrome cardio-rénal de type 1</span> : <span class=\"kw-alerte\">décompensation cardiaque</span> associée à une IRA fonctionnelle (activation du SRAA + sécrétion d'ADH → rétention hydro-sodée et hydrique). À distinguer de l'IRA par DEC : ici, il y a une <strong>surcharge</strong>.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\"><strong>1ʳᵉ intention</strong></span></td><td><span class=\"kw-ttt\">diurétiques</span> + <span class=\"kw-ttt\">optimisation du débit cardiaque</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\"><strong>Si pas de réponse</strong></span></td><td>associer plusieurs <span class=\"kw-ttt\">diurétiques</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\"><strong>Si réfractaire</strong></span></td><td>envisager la <span class=\"kw-alerte\">dialyse</span> (ultrafiltration)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Ne pas confondre avec la DEC.</strong> Devant une IRA fonctionnelle sur <span class=\"kw-ci\">insuffisance cardiaque</span>, le remplissage est <strong>délétère</strong> : le traitement repose sur <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">diurétiques</span> et l'optimisation hémodynamique, pas sur l'expansion volémique.</div>\n      <p><strong>Autres IRA fonctionnelles avec syndrome œdémateux</strong> : <span class=\"kw-alerte\">syndrome hépato-rénal</span> (arrêt <span class=\"kw-ttt\">diurétiques</span> + <span class=\"kw-bio\">albumine</span> + vasoconstricteurs : <span class=\"kw-ttt\">terlipressine</span> ou <span class=\"kw-ttt\">noradrénaline</span>) ; <span class=\"kw-clinique\">syndrome néphrotique</span> (<span class=\"kw-bio\">albumine</span> + <span class=\"kw-ttt\">diurétiques</span> de l'anse IV).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span> · 279 — Cirrhose et complications</em></p>","frequence":2},{"id":"348-19","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la dialyse","contenu":"<p>La dialyse rétablit l'homéostasie par <strong>trois actions</strong> à travers une membrane semi-perméable.</p>\n      <table >\n        <thead><tr><th>Objectif</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\"><strong>Épuration</strong></span></td><td>éliminer <span class=\"kw-clinique\">les</span> déchets métaboliques (<span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">créatinine</span>) et les toxines</td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Correction électrolytique / acido-basique</strong></span></td><td>normaliser K⁺, Na⁺ et <span class=\"kw-bio\">pH</span> (<span class=\"kw-bio\">bicarbonates</span>)</td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Contrôle volémique</strong></span></td><td>soustraire l'excès d'eau (surcharge, <span class=\"kw-alerte\">OAP</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Mécanismes physiques</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Diffusion</span> (gradient de concentration) : épure surtout <span class=\"kw-clinique\">les</span> petites molécules (<span class=\"kw-bio\">urée</span>, K⁺)</li>\n        <li><span class=\"kw-def\">Convection / ultrafiltration</span> (gradient de pression) : soustrait l'eau (perte de poids, <span class=\"kw-alerte\">OAP</span>)</li>\n      </ul>\n      <p><strong>Techniques</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Hémodialyse (HD)</span> : circuit extracorporel, abord vasculaire (<span class=\"kw-clinique\">fistule</span> ou cathéter), <span class=\"kw-ttt\">anticoagulation</span> ; technique majoritaire (&gt;<span class=\"kw-chiffre\"> 90 %</span>)</li>\n        <li><span class=\"kw-ttt\">Dialyse péritonéale (DP)</span> : le péritoine sert de membrane ; souvent à domicile — <span class=\"kw-ci\">non utilisée en situation aiguë</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — IRC · 201 — Transplantation d'organes</em></p>","frequence":1},{"id":"348-20","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications de la dialyse en urgence","contenu":"<p>On distingue <span class=\"kw-clinique\">les</span> indications <strong>vitales immédiates</strong> et les indications de <span class=\"kw-alerte\">réanimation</span> hors <span class=\"kw-alerte\">urgence</span> stricte.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> vitale (<span class=\"kw-alerte\">pronostic vital engagé</span>).</strong></div>\n      <ul>\n        <li><span class=\"kw-alerte\">Hyperkaliémie symptomatique</span> : K⁺ &gt;<span class=\"kw-chiffre\"> 6,5 mmol/L</span> <strong>+ signes <span class=\"kw-imagerie\">ECG</span></strong></li>\n        <li><span class=\"kw-alerte\">Acidose métabolique sévère</span> : <span class=\"kw-bio\">pH</span> &lt; 7,20 (7,15 en <span class=\"kw-alerte\">réanimation</span>)</li>\n        <li><span class=\"kw-alerte\">OAP de surcharge hydro-sodée</span> résistant aux <span class=\"kw-ttt\">diurétiques</span></li>\n      </ul>\n      <p><strong>Autres indications (<span class=\"kw-alerte\">réanimation</span>, hors <span class=\"kw-alerte\">urgence</span> stricte)</strong></p>\n      <ul>\n        <li>Anurie ou oligurie persistant <span class=\"kw-chiffre\">≥ 3 jours</span></li>\n        <li>Complications de l'urémie (<span class=\"kw-bio\">urée</span> <span class=\"kw-chiffre\">&gt; 50 mmol/L</span>) : <span class=\"kw-alerte\">péricardite, coma, hémorragie digestive</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Surveillance</span>.</strong> Ces complications surviennent surtout en cas d'anurie → <span class=\"kw-clinique\">surveillance continue de la diurèse</span> par sonde vésicale à demeure. Bilan préalable : examen cardiovasculaire/pulmonaire, <span class=\"kw-bio\">ionogramme</span> + <span class=\"kw-bio\">bicarbonates</span>, <span class=\"kw-imagerie\">RXT</span>, <span class=\"kw-imagerie\">ECG</span>, <span class=\"kw-bio\">GDS</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectif « principes généraux de la dialyse »</em></p>","frequence":1},{"id":"348-21","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Savoir qu'un épisode d'IRA parenchymateux expose à une insuffisance rénale chronique à long terme et nécessite un suivi","contenu":"<p>Un épisode d'IRA parenchymateuse, <strong>même résolutif</strong>, est un <span class=\"kw-alerte\">facteur de risque d'IRC secondaire</span> pouvant évoluer vers l'<span class=\"kw-ci\">insuffisance rénale</span> terminale.</p>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-def\">Suivi</span> indispensable.</strong> La fonction rénale doit être <span class=\"kw-clinique\">surveillée au cours des mois et années</span> suivant un épisode d'IRA, car le risque d'IRC séquellaire persiste après la phase aiguë.</div>\n      <p><strong><span class=\"kw-def\">Pronostic</span> de la NTA</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Pronostic</span> <span class=\"kw-clinique\">habituellement bon</span> : la fonction rénale revient typiquement à l'état antérieur après <span class=\"kw-chiffre\">1 à 3 semaines</span></li>\n        <li>Récupération par <span class=\"kw-bio\">régénération de l'épithélium tubulaire</span> nécrosé à partir des cellules survivantes</li>\n        <li>Une <span class=\"kw-alerte\">séquelle (IRC)</span> reste néanmoins possible ; le niveau de fonction rénale antérieure conditionne le <span class=\"kw-def\">pronostic</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique · 258 — Élévation de la <span class=\"kw-bio\">créatininémie</span></em></p>","frequence":1},{"id":"348-22","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les différentes évolutions possibles d'une nécrose tubulaire aiguë (NTA)","contenu":"<p>L'<span class=\"kw-clinique\">évolution</span> d'une NTA dépend du <span class=\"kw-def\">terrain</span>, du contexte initial et de la survenue de complications.</p>\n      <p><strong>Facteurs de gravité / d'<span class=\"kw-clinique\">évolution</span> défavorable</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\">Choc septique initial</span></li>\n        <li><span class=\"kw-alerte\">Défaillances d'organe associées</span></li>\n        <li><span class=\"kw-clinique\">Complications de l'IRA</span> : hyperkaliémie, acidose métabolique, surcharge hydro-sodée, dénutrition, infections nosocomiales, hémorragies digestives</li>\n        <li><span class=\"kw-clinique\">Terrain</span> : <span class=\"kw-def\">comorbidités</span> cardiovasculaires, fragilité, <span class=\"kw-etio\">diabète</span></li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Évolution</span></th><th>Données</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Récupération</strong></span></td><td>fonction rénale revenant à l'état antérieur en <span class=\"kw-chiffre\">1-3 semaines</span> (régénération tubulaire)</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Séquelle</strong></span></td><td><span class=\"kw-etio\">IRC</span> possible (FR d'<span class=\"kw-clinique\">évolution</span> vers l'IRT)</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Mortalité</strong></span></td><td>mono-<span class=\"kw-alerte\">défaillance</span> rénale : <span class=\"kw-chiffre\">10 %</span> ; IRA en <span class=\"kw-alerte\">réanimation</span> (après <span class=\"kw-alerte\">choc</span> / <span class=\"kw-ttt\">chirurgie</span> lourde) : <span class=\"kw-chiffre\">40 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Prévention des complications.</strong> Adaptation des posologies, prévention des hémorragies digestives (<span class=\"kw-ttt\">IPP</span>), prévention de la dénutrition (apports caloriques 20-40 cal/kg/j et azotés <span class=\"kw-chiffre\">0,2-0,3 g</span>/kg/j). L'acidose métabolique n'est généralement pas corrigée à la phase aiguë (sauf <span class=\"kw-bio\">pH</span> &lt; 7,20 ou pertes digestives de <span class=\"kw-bio\">bicarbonates</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — IRC · 332 — États de <span class=\"kw-alerte\">choc</span></em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Indications de dialyse en <span class=\"kw-alerte\">urgence</span> <span class=\"q\">— <span class=\"kw-alerte\">pronostic vital engagé</span></span></strong></p><p>bilan minute : <span class=\"kw-bio\">ionogramme + bicarbonates</span>, <span class=\"kw-bio\">ECG</span>, <span class=\"kw-bio\">gaz du sang</span>, <span class=\"kw-imagerie\">RXT</span></p><ul><li><span class=\"kw-alerte\">Hyperkaliémie symptomatique</span> : <span class=\"kw-bio\">K⁺</span> <span class=\"kw-chiffre\">&gt; 6,5 mmol/L</span> + <span class=\"kw-bio\">signes ECG</span></li><li><span class=\"kw-alerte\">Acidose métabolique sévère</span> : <span class=\"kw-chiffre\">pH &lt; 7,20</span> (<span class=\"kw-chiffre\">7,15</span> en <span class=\"kw-alerte\">réanimation</span>)</li><li><span class=\"kw-alerte\">OAP de surcharge hydro-sodée</span> résistant aux <span class=\"kw-ttt\">diurétiques</span></li></ul><p><strong>IRA obstructive <span class=\"q\">— lever l'obstacle</span></strong></p><p>d'abord éliminer une <span class=\"kw-alerte\">indication de dialyse en urgence</span>, puis <span class=\"kw-imagerie\">échographie réno-vésicale</span></p><ul><li><span class=\"kw-def\">Lever l'obstacle</span> immédiatement pour rétablir l'écoulement des urines</li><li><span class=\"kw-clinique\">Globe vésical</span> → <span class=\"kw-ttt\">sondage vésical</span> ou <span class=\"kw-ttt\">cathéter sus-pubien</span></li><li><span class=\"kw-clinique\">Anurie / obstacle haut</span> → <span class=\"kw-ttt\">sonde JJ (urétérale)</span> ou <span class=\"kw-ttt\">néphrostomie percutanée</span></li></ul><p><strong>IRA fonctionnelle <span class=\"q\">— restaurer la perfusion</span></strong></p><p><span class=\"kw-clinique\">déshydratation</span> → <span class=\"kw-ttt\">remplissage (NaCl isotonique)</span> · <span class=\"kw-clinique\">insuffisance cardiaque</span> → <span class=\"kw-ttt\">diurétiques</span> (pas de remplissage)</p><ul><li>Réversible si la <span class=\"kw-clinique\">perfusion rénale</span> est rétablie sans délai (sinon <span class=\"kw-clinique\">évolution</span> vers <span class=\"kw-alerte\">NTA ischémique</span>)</li><li>Reprise de la <span class=\"kw-clinique\">diurèse</span> en quelques heures = 1ᵉʳ signe favorable</li></ul>","hospit":"<p><strong>Avis néphrologique</strong></p><ul><li>Suspicion d'<span class=\"kw-def\">IRA organique non-NTA</span> : signes glomérulaires (<span class=\"kw-bio\">protéinurie &gt; 1 g/j</span>, <span class=\"kw-clinique\">hématurie</span>, <span class=\"kw-clinique\">HTA</span>, <span class=\"kw-clinique\">œdèmes</span>) ou vasculaires → discuter une <span class=\"kw-imagerie\">PBR</span></li><li>Suspicion de <span class=\"kw-alerte\">glomérulonéphrite rapidement progressive (GNRP)</span> ou de <span class=\"kw-alerte\">vascularite</span> (<span class=\"kw-alerte\">urgence</span> diagnostique et thérapeutique)</li><li><span class=\"kw-clinique\">Doute aigu / chronique</span> persistant, ou IRA sur <span class=\"kw-def\">IRC</span> évoluée</li><li><span class=\"kw-alerte\">Indication potentielle d'épuration extra-rénale</span> (hyperkaliémie / acidose / surcharge menaçantes)</li></ul><p><strong>Avis urologique</strong></p><ul><li><span class=\"kw-def\">IRA obstructive</span> confirmée → dérivation des urines</li><li>Patient <span class=\"kw-clinique\">hospitalisé</span>, <span class=\"kw-ttt\">médicaments néphrotoxiques arrêtés</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Hyperkaliémie</span> avec <span class=\"kw-bio\">signes ECG</span> (formes anuriques ++)</li><li><span class=\"kw-alerte\">Acidose métabolique</span> à <span class=\"kw-bio\">trou anionique augmenté</span></li><li><span class=\"kw-alerte\">Surcharge hydro-sodée</span> : <span class=\"kw-clinique\">HTA</span>, <span class=\"kw-clinique\">œdèmes</span>, épanchements séreux voire <span class=\"kw-alerte\">OAP</span></li><li><span class=\"kw-alerte\">Syndrome urémique</span> : <span class=\"kw-clinique\">confusion</span>, <span class=\"kw-clinique\">astérixis</span> ; si <span class=\"kw-bio\">urée &gt; 50 mmol/L</span> → <span class=\"kw-alerte\">péricardite</span>, <span class=\"kw-alerte\">coma</span>, <span class=\"kw-alerte\">hémorragie digestive</span></li><li><span class=\"kw-alerte\">Anurie</span> (<span class=\"kw-chiffre\">&lt; 100-200 mL/24 h</span>) ou <span class=\"kw-clinique\">oligurie</span> persistante</li><li>IRA obstructive : <span class=\"kw-clinique\">douleur lombaire</span>, <span class=\"kw-clinique\">hématurie macroscopique avec caillots</span>, <span class=\"kw-clinique\">globe vésical</span></li><li><span class=\"kw-def\">SHU</span> (enfant <span class=\"kw-chiffre\">&lt; 3 ans</span>) : triade <span class=\"kw-alerte\">anémie hémolytique mécanique + thrombopénie + IRA</span></li></ul>","principes":"<p>Trois axes : <strong>traiter la cause</strong> (remplissage, levée d'obstacle, traitement spécifique), <strong>corriger <span class=\"kw-clinique\">les</span> complications métaboliques menaçantes</strong>, et <strong>arrêter / adapter les néphrotoxiques</strong> (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">IEC/ARA2</span>, <span class=\"kw-ttt\">diurétiques</span>).</p><p><strong>IRA fonctionnelle par <span class=\"kw-clinique\">déshydratation</span> extra-cellulaire</strong></p><p>reprise de la <span class=\"kw-clinique\">diurèse</span> en quelques heures = efficacité (confirme le caractère fonctionnel)</p><ul><li>Corriger la <span class=\"kw-clinique\">DEC</span> : <span class=\"kw-ttt\">sel de table / gélules de NaCl</span> per os, ou <span class=\"kw-ttt\">cristalloïde (NaCl isotonique)</span> IV</li><li>Arrêt des <span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-ttt\">AINS</span>, antihypertenseurs ; <strong>arrêt du régime sans sel</strong></li></ul><p><strong>IRA fonctionnelle par <span class=\"kw-ci\">insuffisance cardiaque</span> <span class=\"q\">— syndrome cardio-rénal type 1</span></strong></p><p><span class=\"kw-ci\">remplissage délétère</span> ici (il y a une surcharge, pas une DEC)</p><ul><li>1ʳᵉ intention : <span class=\"kw-ttt\">diurétiques</span> + <span class=\"kw-ttt\">optimisation du débit cardiaque</span></li><li>Si pas de réponse : associer plusieurs <span class=\"kw-ttt\">diurétiques</span> ; si réfractaire → <span class=\"kw-alerte\">dialyse</span> (ultrafiltration)</li></ul><p><strong>IRA obstructive + <span class=\"kw-clinique\">syndrome de levée</span> d'obstacle</strong></p><p><span class=\"kw-ci\">UIV / uro-TDM injectés</span> <span class=\"kw-ci\">contre-indiqués</span> (PDC iodé <span class=\"kw-ci\">proscrit</span>)</p><ul><li><span class=\"kw-def\">Lever l'obstacle</span> : <span class=\"kw-ttt\">sondage vésical</span> / <span class=\"kw-ttt\">cathéter sus-pubien</span> (globe) ; <span class=\"kw-ttt\">sonde JJ</span> ou <span class=\"kw-ttt\">néphrostomie percutanée</span> (obstacle haut)</li><li>Si <span class=\"kw-alerte\">sepsis</span> : <span class=\"kw-ttt\">C3G IV + amikacine</span> après prélèvements bactériologiques</li><li><span class=\"kw-alerte\">Syndrome de levée d'obstacle</span> : <span class=\"kw-clinique\">polyurie massive</span> → compensation IV « volume pour volume » (<span class=\"kw-ttt\">NaCl isotonique</span>)</li></ul><p><strong>IRA organique / NTA</strong></p><ul><li>Traiter <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">troubles hydro-électrolytiques</span> : <span class=\"kw-ttt\">traitement de l'hyperkaliémie</span> (sel de calcium, G<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>10</span> %</span> + <span class=\"kw-ttt\">insuline</span>, <span class=\"kw-ttt\">salbutamol</span>, résines), <span class=\"kw-ttt\">diurétique de l'anse</span> sur la surcharge</li><li><span class=\"kw-ci\">Acidose métabolique non corrigée à la phase aiguë</span> sauf <span class=\"kw-chiffre\">pH &lt; 7,20</span> ou pertes digestives de <span class=\"kw-bio\">bicarbonates</span></li><li>Prévention : <span class=\"kw-ttt\">IPP</span> (hémorragies digestives), nutrition (<span class=\"kw-chiffre\">20-40 cal/kg/j</span> · <span class=\"kw-chiffre\">0,2-0,3 g/kg/j</span> d'azote)</li></ul><p><strong>Adaptation des médicaments & prévention de la néphrotoxicité</strong></p><ul><li>Adapter / arrêter <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">néphrotoxiques</span> ; <span class=\"kw-ttt\">monitorage de la concentration plasmatique</span> si disponible (<span class=\"kw-bio\">créatinine</span> = marqueur retardé en IRA)</li><li><span class=\"kw-ttt\">Produits de contraste iodés</span> : <span class=\"kw-ttt\">hydratation</span> (NaCl <span class=\"kw-chiffre\">9 ‰</span> ou <span class=\"kw-bio\">bicarbonate</span> <span class=\"kw-chiffre\">1,4 %</span>), arrêt <span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">diurétiques</span> / <span class=\"kw-ttt\">metformine</span></li><li>Syndromes de lyse (rhabdomyolyse, lyse <span class=\"kw-etio\">tumorale</span>) : <span class=\"kw-ttt\">hydratation abondante</span></li></ul><p><strong>Dialyse</strong></p><ul><li>Triple action : <span class=\"kw-ttt\">épuration</span> (<span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">créatinine</span>), <span class=\"kw-ttt\">correction électrolytique / acido-basique</span>, <span class=\"kw-ttt\">contrôle volémique</span></li><li><span class=\"kw-ttt\">Hémodialyse</span> = technique majoritaire (<span class=\"kw-chiffre\">&gt; 90 %</span>) en aigu ; <span class=\"kw-ttt\">dialyse péritonéale</span> <span class=\"kw-ci\">non utilisée en situation aiguë</span></li></ul>","suivi":"<p><strong>Après IRA parenchymateuse :</strong> <span class=\"kw-def\">surveillance</span> de la <span class=\"kw-clinique\">fonction rénale</span> pendant des mois / années — <span class=\"kw-alerte\">facteur de risque d'IRC secondaire</span> (voire <span class=\"kw-ci\">insuffisance rénale</span> terminale).<br><strong>NTA :</strong> récupération en <span class=\"kw-chiffre\">1 à 3 semaines</span> (régénération de l'épithélium tubulaire), mais <span class=\"kw-alerte\">séquelle (IRC)</span> possible ; <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">10 %</span> (mono-<span class=\"kw-alerte\">défaillance</span>) à <span class=\"kw-chiffre\">40 %</span> (<span class=\"kw-alerte\">réanimation</span>).<br><strong><span class=\"kw-def\">Surveillance</span> aiguë :</strong> <span class=\"kw-clinique\">diurèse</span> en continu (sonde vésicale à demeure), <span class=\"kw-bio\">ionogramme</span>, poids, <span class=\"kw-clinique\">PA</span>.<br><strong><span class=\"kw-clinique\">Syndrome de levée</span> d'obstacle :</strong> <span class=\"kw-clinique\">diurèse horaire</span>, <span class=\"kw-bio\">ionogrammes sang/urine</span> répétés, compensation hydro-électrolytique progressive.</p>"},"liensGlobaux":[{"href":"https://manuel4.cuen.fr/spip.php?rubrique16","label":"Collège CUEN — Insuffisance rénale aiguë"},{"href":"https://radiopaedia.org/articles/obstructive-uropathy","label":"Radiopaedia : Obstructive uropathy"}],"cards":[{"i":"0d778bd34e66","n":348,"o":"348-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'une insuffisance rénale aiguë (IRA) et de sa sévérité (oligurie, anurie) chez l'adulte et l'enfant","q":"Comment définir une Insuffisance Rénale Aiguë (IRA) ?","a":"<p>L'Insuffisance Rénale Aiguë (IRA) se définit par une <strong>altération rapide de la fonction rénale glomérulaire</strong>. Sa reconnaissance repose sur :</p><ul><li>Une <strong>élévation de la créatinine plasmatique</strong>.</li><li>Le <strong>volume de la diurèse</strong>.</li></ul>"},{"i":"3d634ff9da2d","n":348,"o":"348-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'une insuffisance rénale aiguë (IRA) et de sa sévérité (oligurie, anurie) chez l'adulte et l'enfant","q":"Quel est le principe de l'évaluation de la créatininémie de référence pour le diagnostic d'une Insuffisance Rénale Aiguë (IRA) ?","a":"<p>On se base sur la <strong>créatininémie connue la plus récente</strong>. En cas de doute sur le caractère aigu ou chronique de l'insuffisance rénale, il est toujours préférable de la considérer comme <strong>aiguë</strong>.</p>"},{"i":"d67990647c18","n":348,"o":"348-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'une insuffisance rénale aiguë (IRA) et de sa sévérité (oligurie, anurie) chez l'adulte et l'enfant","q":"Quel est le piège physiologique concernant l'estimation du DFG en cas d'Insuffisance Rénale Aiguë (IRA) ?","a":"<p>En Insuffisance Rénale Aiguë (IRA), la fonction rénale est <strong>instable</strong>. Il n'est pas possible d'estimer le <strong>Débit de Filtration Glomérulaire (DFG)</strong> car la créatinine est un marqueur indirect et retardé. Le raisonnement doit se baser sur la <strong>cinétique de la créatinine</strong> et la <strong>diurèse</strong>, et non sur un DFG estimé.</p>"},{"i":"ede5fa440a8d","n":348,"o":"348-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'une insuffisance rénale aiguë (IRA) et de sa sévérité (oligurie, anurie) chez l'adulte et l'enfant","q":"Comment classifie-t-on la sévérité d'une Insuffisance Rénale Aiguë (IRA) en fonction de la créatinine et de la diurèse ?","a":"<ul><li><strong>Stade 1</strong>: <ul><li>Créatininémie: augmentation > <strong>26 µmol/L en 48 h</strong>, ou > <strong>50 % en 7 jours</strong>.</li><li>Diurèse: < <strong>0,5 mL/kg/h</strong> pendant <strong>6-12 h</strong>.</li></ul></li><li><strong>Stade 2</strong>: <ul><li>Créatininémie: <strong>multipliée par 2</strong> en 7 jours.</li><li>Diurèse: < <strong>0,5 mL/kg/h</strong> pendant ≥ <strong>12 h</strong>.</li></ul></li><li><strong>Stade 3</strong>: <ul><li>Créatininémie: <strong>multipliée par 3</strong> en 7 jours, ou > <strong>354 µmol/L</strong>, ou nécessité de dialyse.</li><li>Diurèse: < <strong>0,3 mL/kg/h</strong> pendant ≥ <strong>24 h</strong>, ou <strong>anurie</strong> pendant ≥ <strong>12 h</strong>.</li></ul></li></ul>"},{"i":"f87a1dbc3c85","n":348,"o":"348-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'une insuffisance rénale aiguë (IRA) et de sa sévérité (oligurie, anurie) chez l'adulte et l'enfant","q":"Comment définit-on l'oligurie et l'anurie chez un patient présentant une Insuffisance Rénale Aiguë (IRA) ?","a":"<ul><li><strong>Oligurie</strong>: Diurèse < <strong>0,5 mL/kg/h</strong>.</li><li><strong>Anurie</strong>: Diurèse < <strong>100-200 mL/24 h</strong>, avec la vessie vide.</li></ul>"},{"i":"0b9099d7f712","n":348,"o":"348-13","u":"Étiologies","t":"Connaître les principales causes d'IRA chez l'enfant (SHU, déshydratation, choc...) et les mesures hygiéno-diététiques de prévention des SHU","q":"Quelles sont les principales causes d'insuffisance rénale aiguë (IRA) obstructive ou post-rénale chez l'enfant ?","a":"<p>Chez l'enfant, les causes d'IRA obstructive sont :</p><ul><li>Les <strong>uropathies malformatives</strong> (par exemple les valves de l'urètre postérieur).</li><li>Les <strong>lithiases</strong>.</li><li>Les <strong>tumeurs</strong>.</li></ul>"},{"i":"b797980c91a8","n":348,"o":"348-13","u":"Étiologies","t":"Connaître les principales causes d'IRA chez l'enfant (SHU, déshydratation, choc...) et les mesures hygiéno-diététiques de prévention des SHU","q":"Quelles sont les mesures de prévention du syndrome hémolytique et urémique (SHU) chez l'enfant, particulièrement importantes avant 3 ans ?","a":"<p>Les mesures de prévention du SHU, cruciales avant 3 ans, sont :</p><ul><li><strong>Cuisson des viandes</strong> : bien cuire le bœuf, surtout haché (à cœur, pas de viande rosée).</li><li><strong>Produits laitiers</strong> : éviter les fromages au lait cru et le lait non pasteurisé.</li><li><strong>Végétaux</strong> : laver soigneusement les fruits, légumes et herbes (surtout crus).</li><li><strong>Hygiène</strong> : lavage fréquent des mains (avant les repas, après les toilettes/le change) ; nettoyer les ustensiles et les plans de travail ayant touché de la viande crue.</li><li><strong>Environnement</strong> : éviter le contact direct avec les bovins/ovins et leur environnement.</li><li><strong>Comportement</strong> : éviter la baignade en lieu public en cas de diarrhée de l'enfant.</li></ul>"},{"i":"b86cd8118a82","n":348,"o":"348-13","u":"Étiologies","t":"Connaître les principales causes d'IRA chez l'enfant (SHU, déshydratation, choc...) et les mesures hygiéno-diététiques de prévention des SHU","q":"Quelles sont les principales causes d'insuffisance rénale aiguë (IRA) organique ou parenchymateuse chez l'enfant ?","a":"<p>Chez l'enfant, les causes d'IRA organique sont :</p><ul><li>Le <strong>syndrome hémolytique et urémique (SHU)</strong>, qui est la <strong>première cause</strong> d'IRA organique chez l'enfant de <strong>moins de 3 ans</strong>.</li><li>La <strong>nécrose tubulaire aiguë (NTA)</strong> due à un choc ou une ischémie.</li><li>Les <strong>glomérulonéphrites</strong> (post-infectieuse, rapidement progressive).</li></ul>"},{"i":"c05260760261","n":348,"o":"348-13","u":"Étiologies","t":"Connaître les principales causes d'IRA chez l'enfant (SHU, déshydratation, choc...) et les mesures hygiéno-diététiques de prévention des SHU","q":"Quelles sont les principales causes d'insuffisance rénale aiguë (IRA) fonctionnelle ou pré-rénale chez l'enfant ?","a":"<p>Chez l'enfant, les causes d'IRA fonctionnelle sont :</p><ul><li>La <strong>déshydratation aiguë</strong> (gastro-entérite aiguë, pertes digestives).</li><li>Le <strong>syndrome néphrotique</strong>.</li><li>Les <strong>brûlures</strong>.</li><li>L'<strong>hémorragie</strong>.</li><li>Les <strong>états de choc</strong> (septique, cardiogénique).</li><li>Les <strong>AINS</strong> et les <strong>IEC</strong>, surtout en contexte de déshydratation.</li></ul>"},{"i":"fa1548f7e682","n":348,"o":"348-13","u":"Étiologies","t":"Connaître les principales causes d'IRA chez l'enfant (SHU, déshydratation, choc...) et les mesures hygiéno-diététiques de prévention des SHU","q":"Qu'est-ce que le syndrome hémolytique et urémique (SHU) typique et quelle en est la cause principale chez l'enfant ?","a":"<p>Le <strong>syndrome hémolytique et urémique (SHU) typique</strong> est une <strong>microangiopathie thrombotique</strong> associant la triade :</p><ul><li><strong>Anémie hémolytique mécanique</strong>.</li><li><strong>Thrombopénie</strong>.</li><li><strong>Insuffisance rénale aiguë (IRA)</strong>.</ul><p>Sa cause est une <strong>toxi-infection alimentaire à <em>E. coli</em> producteur de Shigatoxines (STEC)</strong>, souvent après une diarrhée (parfois sanglante).</p>"},{"i":"05da8bcf1d62","n":348,"o":"348-14","u":"Identifier une urgence","t":"Connaître les signes cliniques et biologiques imposant une prise en charge urgente en milieu spécialisé d'une IRA","q":"Quelle est la définition de l'acidose métabolique en cas d'insuffisance rénale aiguë (IRA) et dans quelles situations est-elle plus marquée ?","a":"L'acidose métabolique est à <strong>trou anionique augmenté</strong>. Elle est plus marquée dans :\n<ul>\n  <li>Les IRA <strong>obstructives</strong>.</li>\n  <li>L'intoxication à l'<strong>éthylène glycol</strong>.</li>\n  <li>Les états de <strong>choc</strong> (acidose lactique).</li>\n  <li>L'<strong>acidocétose</strong>.</li>\n  <li>Les <strong>diarrhées</strong>.</li>\n</ul>"},{"i":"149ba6d4839e","n":348,"o":"348-14","u":"Identifier une urgence","t":"Connaître les signes cliniques et biologiques imposant une prise en charge urgente en milieu spécialisé d'une IRA","q":"Quels sont les signes du syndrome urémique en cas d'insuffisance rénale aiguë (IRA) et quand apparaissent les formes graves ?","a":"Les signes du syndrome urémique incluent :\n<ul>\n  <li><strong>Anorexie</strong>, <strong>nausées</strong>, <strong>vomissements</strong>.</li>\n  <li><strong>Confusion</strong>, <strong>astérixis</strong>, <strong>ROT vifs</strong>, <strong>épilepsie</strong>.</li>\n</ul>\nSi l'<strong>urée dépasse 50 mmol/L</strong>, des formes graves peuvent apparaître :\n<ul>\n  <li><strong>Péricardite</strong>.</li>\n  <li><strong>Coma</strong>.</li>\n  <li><strong>Hémorragie digestive</strong>.</li>\n</ul>"},{"i":"291f5882d839","n":348,"o":"348-14","u":"Identifier une urgence","t":"Connaître les signes cliniques et biologiques imposant une prise en charge urgente en milieu spécialisé d'une IRA","q":"Quels sont les signes cliniques et paracliniques de la surcharge hydro-sodée en cas d'insuffisance rénale aiguë (IRA) ?","a":"La surcharge hydro-sodée se manifeste par :\n<ul>\n  <li>Une <strong>HTA</strong>.</li>\n  <li>Des <strong>œdèmes déclives</strong>.</li>\n  <li>Des <strong>épanchements séreux</strong> (plèvre, péricarde).</li>\n  <li>Voire un <strong>Œdème Aigu du Poumon (OAP)</strong>.</li>\n</ul>"},{"i":"4608afdadaa3","n":348,"o":"348-14","u":"Identifier une urgence","t":"Connaître les signes cliniques et biologiques imposant une prise en charge urgente en milieu spécialisé d'une IRA","q":"Quels bilans urgents doivent être réalisés devant une suspicion d'insuffisance rénale aiguë (IRA) avec complications menaçant le pronostic vital ?","a":"Les bilans urgents à réaliser sont :\n<ul>\n  <li>Un <strong>examen cardiovasculaire</strong> et une <strong>auscultation pulmonaire</strong>.</li>\n  <li>Un <strong>ionogramme</strong> et des <strong>bicarbonates plasmatiques</strong>.</li>\n  <li>Une <strong>radiographie thoracique (RXT)</strong>.</li>\n  <li>Un <strong>électrocardiogramme (ECG)</strong>.</li>\n  <li>Des <strong>gaz du sang</strong>.</li>\n</ul>"},{"i":"4c4f8cf907bb","n":348,"o":"348-14","u":"Identifier une urgence","t":"Connaître les signes cliniques et biologiques imposant une prise en charge urgente en milieu spécialisé d'une IRA","q":"Quels sont les éléments clés et les facteurs aggravants de l'hyperkaliémie en cas d'insuffisance rénale aiguë (IRA) ?","a":"L'hyperkaliémie est due à une <strong>baisse de la sécrétion tubulaire de K⁺</strong>, surtout dans les formes anuriques d'IRA. Elle peut être aggravée par :\n<ul>\n  <li>Les <strong>anti-aldostérones</strong>, <strong>IEC</strong> / <strong>ARA2</strong>.</li>\n  <li>Le <strong>triméthoprime-sulfaméthoxazole</strong>.</li>\n  <li>Le <strong>relargage cellulaire</strong> (acidose, rhabdomyolyse, hémolyse, lyse tumorale).</li>\n</ul>"},{"i":"c73878e7132a","n":348,"o":"348-14","u":"Identifier une urgence","t":"Connaître les signes cliniques et biologiques imposant une prise en charge urgente en milieu spécialisé d'une IRA","q":"Quelles sont les indications de dialyse en urgence lors d'une insuffisance rénale aiguë (IRA) ?","a":"Les indications de dialyse en urgence sont :\n<ul>\n  <li>Une <strong>hyperkaliémie symptomatique</strong> (K⁺ > 6,5 mmol/L + signes ECG).</li>\n  <li>Une <strong>acidose métabolique sévère</strong> (pH < 7,20 ; ou < 7,15 en réanimation).</li>\n  <li>Un <strong>Œdème Aigu du Poumon (OAP) de surcharge résistant aux diurétiques</strong>.</li>\n</ul>"},{"i":"e54b63ba6713","n":348,"o":"348-14","u":"Identifier une urgence","t":"Connaître les signes cliniques et biologiques imposant une prise en charge urgente en milieu spécialisé d'une IRA","q":"Quelles sont les quatre complications métaboliques engageant le pronostic vital et imposant une prise en charge urgente en milieu spécialisé lors d'une insuffisance rénale aiguë (IRA) ?","a":"Les quatre complications métaboliques de l'IRA sont :\n<ul>\n  <li>L'<strong>hyperkaliémie</strong>.</li>\n  <li>L'<strong>acidose métabolique</strong>.</li>\n  <li>La <strong>surcharge hydro-sodée</strong>.</li>\n  <li>Le <strong>syndrome urémique</strong>.</li>\n</ul>"},{"i":"2c92e7ebd758","n":348,"o":"348-15","u":"Prise en charge","t":"Connaître les modalités d'adaptation de la prescription des médicaments et des examens complémentaires à la sévérité de l'insuffisance rénale","q":"Comment prévenir la néphrotoxicité liée aux produits de contraste iodés (PCI) chez un patient à risque d'IRA ?","a":"<p>Pour prévenir la néphrotoxicité des PCI, il est recommandé d'<strong>arrêter les AINS et diurétiques</strong>, d'<strong>arrêter la metformine</strong> le jour de l'examen et pendant <strong>48 heures</strong> après. Il faut privilégier les PCI de <strong>faible/iso-osmolarité</strong> et en <strong>volume limité</strong>. Une <strong>hydratation</strong> adéquate est cruciale, généralement avec du <strong>NaCl 9‰</strong> ou du <strong>bicarbonate 1,4%</strong>, à raison de <strong>1 mL/kg/h</strong>, <strong>12 heures avant et après</strong> l'injection.</p>"},{"i":"4e54c36a8d14","n":348,"o":"348-15","u":"Prise en charge","t":"Connaître les modalités d'adaptation de la prescription des médicaments et des examens complémentaires à la sévérité de l'insuffisance rénale","q":"Quelles sont les stratégies générales pour adapter la posologie d'un médicament en cas d'insuffisance rénale ?","a":"<p>Les stratégies d'adaptation de la posologie reposent soit sur une <strong>diminution de la dose</strong> (pour les médicaments à index thérapeutique étroit ou à demi-vie courte), soit sur un <strong>espacement des prises</strong> (pour ceux à demi-vie longue ou à index thérapeutique large), voire une combinaison des deux.</p>"},{"i":"71f3851c4f84","n":348,"o":"348-15","u":"Prise en charge","t":"Connaître les modalités d'adaptation de la prescription des médicaments et des examens complémentaires à la sévérité de l'insuffisance rénale","q":"Quelles mesures spécifiques sont nécessaires pour prévenir la néphrotoxicité des médicaments néphrotoxiques comme les aminosides ou le cisplatine ?","a":"<p>Pour les médicaments néphrotoxiques, il est essentiel d'<strong>adapter la posologie</strong>. Des <strong>dosages résiduels</strong> sont nécessaires si la durée de traitement dépasse <strong>48 heures</strong>. Une <strong>hydratation</strong> suffisante est également primordiale.</p>"},{"i":"818979929836","n":348,"o":"348-15","u":"Prise en charge","t":"Connaître les modalités d'adaptation de la prescription des médicaments et des examens complémentaires à la sévérité de l'insuffisance rénale","q":"Comment l'insuffisance rénale modifie-t-elle la pharmacocinétique des médicaments ?","a":"<p>L'insuffisance rénale altère la pharmacocinétique de plusieurs manières, notamment la <strong>biodisponibilité</strong>, le <strong>volume de distribution</strong>, la <strong>liaison protéique</strong> (augmentant la fraction libre par hypoalbuminémie et toxines urémiques) et l'<strong>élimination</strong>, qu'elle soit hépatique ou rénale.</p>"},{"i":"ba51d0b16c55","n":348,"o":"348-15","u":"Prise en charge","t":"Connaître les modalités d'adaptation de la prescription des médicaments et des examens complémentaires à la sévérité de l'insuffisance rénale","q":"Quelles sont les précautions spécifiques à prendre en cas d'insuffisance rénale aiguë (IRA) pour l'adaptation des doses médicamenteuses ?","a":"<p>En cas d'IRA, il n'existe pas de moyen simple et fiable de mesurer la fonction rénale car la créatinine est un marqueur retardé. Il est donc recommandé d'effectuer un <strong>monitorage de la concentration plasmatique</strong> du médicament lorsque c'est disponible. Il est important de se souvenir que l'altération des fonctions tubulaires n'est pas proportionnelle au DFG estimé en IRA, rendant l'adaptation posologique complexe.</p>"},{"i":"c35b87f334b4","n":348,"o":"348-15","u":"Prise en charge","t":"Connaître les modalités d'adaptation de la prescription des médicaments et des examens complémentaires à la sévérité de l'insuffisance rénale","q":"Quelles sont les méthodes d'évaluation de la fonction rénale à privilégier pour l'adaptation des doses médicamenteuses ?","a":"<p>Pour évaluer la fonction rénale, il faut considérer des éléments cliniques (<strong>poids</strong>, <strong>volume extra-cellulaire</strong>). L'estimation du débit de filtration glomérulaire (DFG) se fait préférentiellement par l'équation <strong>CKD-EPI</strong>. L'équation de Cockcroft est parfois retenue pour l'adaptation des doses (car historiquement présente dans les RCP) mais elle est moins fiable chez le sujet âgé ou en surpoids.</p>"},{"i":"0ba0ba5ae22c","n":348,"o":"348-16","u":"Prise en charge","t":"Connaître le traitement d'une IRA obstructive et la prise en charge d'un syndrome de levée d'obstacle","q":"Comment prend-on en charge un obstacle bas (globe vésical) en cas d'IRA obstructive ?","a":"<p>En cas de <strong>globe vésical</strong> provoquant une IRA obstructive, le drainage s'effectue par :</p><ul><li>Un <a class=\"keyword\" href=\"https://www.wikimedecine.fr/sondage-vesical\">sondage vésical</a>.</li><li>Un <a class=\"keyword\" href=\"https://www.wikimedecine.fr/catheter-sus-pubien\">cathéter sus-pubien</a>, si le sondage vésical est impossible.</li></ul>"},{"i":"1623fb6a8efc","n":348,"o":"348-16","u":"Prise en charge","t":"Connaître le traitement d'une IRA obstructive et la prise en charge d'un syndrome de levée d'obstacle","q":"Comment survient et se prend en charge le syndrome de levée d'obstacle après dérivation d'une IRA obstructive ?","a":"<p>Le <strong>syndrome de levée d'obstacle</strong> survient après la dérivation et se caractérise par une <strong>polyurie massive</strong>, entraînant un risque de déshydratation et d'hypokaliémie. La surveillance de ce syndrome inclut :</p><ul><li>Une diurèse horaire.</li><li>Le poids.</li><li>La pression artérielle (PA).</li><li>Des ionogrammes sanguins et urinaires répétés.</li></ul><p>La compensation hydro-électrolytique IV est initialement de type <strong>« volume pour volume »</strong> avec du <strong>NaCl isotonique</strong>, puis progressivement diminuée.</p>"},{"i":"2572ea037a96","n":348,"o":"348-16","u":"Prise en charge","t":"Connaître le traitement d'une IRA obstructive et la prise en charge d'un syndrome de levée d'obstacle","q":"Quelle est la prise en charge initiale d'une insuffisance rénale aiguë (IRA) obstructive ?","a":"<p>La prise en charge initiale d'une IRA obstructive consiste à :</p><ul><li>Hospitaliser le patient.</li><li>Arrêter les médicaments <a class=\"keyword\" href=\"https://www.wikimedecine.fr/nephrotoxique\">néphrotoxiques</a>.</li><li>D'abord, éliminer une indication de dialyse en urgence.</li><li>Réaliser une échographie réno-vésicale avec ou sans TDM abdomino-pelvienne non injectée.</li></ul>"},{"i":"8ced18292b77","n":348,"o":"348-16","u":"Prise en charge","t":"Connaître le traitement d'une IRA obstructive et la prise en charge d'un syndrome de levée d'obstacle","q":"Quelles sont les complications à surveiller après la dérivation d'une IRA obstructive et comment les prévenir ou les détecter ?","a":"<p>Les complications à surveiller après la dérivation d'une IRA obstructive sont :</p><ul><li>L'<strong>hémorragie vésicale a vacuo</strong>, prévenue par un <strong>clampage</strong> tous les <strong>300-500 mL</strong> ou toutes les <strong>30 minutes</strong> lors du drainage d'un globe vésical.</li><li>Le <strong>saignement</strong>.</li><li>La <strong>fistule</strong>.</li><li>La <strong>pyélonéphrite aiguë (PNA)</strong> en cas de néphrostomie.</li></ul><p>Les UIV et uro-TDM injectés sont contre-indiqués en raison des risques liés au produit de contraste iodé.</p>"},{"i":"ae8d0fc67b73","n":348,"o":"348-16","u":"Prise en charge","t":"Connaître le traitement d'une IRA obstructive et la prise en charge d'un syndrome de levée d'obstacle","q":"Comment prend-on en charge un obstacle haut ou une anurie en cas d'IRA obstructive, et quelles sont les particularités en cas de sepsis ?","a":"<p>En cas d'<strong>obstacle haut</strong> ou d'<strong>anurie</strong> par IRA obstructive, la dérivation se fait au-dessus de l'obstacle par :</p><ul><li>Pose d'une <strong>sonde JJ urétérale</strong> par voie endoscopique.</li><li>Ou une <strong>néphrostomie percutanée</strong> sous échographie, présentant un risque hémorragique plus élevé.</li></ul><p>En cas de <strong>sepsis</strong> associé, une antibiothérapie par <strong>C3G IV</strong> associée à de l'<strong>amikacine</strong> est initiée après prélèvements (avec ± couverture des EBLSE).</p>"},{"i":"14e9156a2685","n":348,"o":"348-17","u":"Prise en charge","t":"Connaître la prise en charge d'une IRA fonctionnelle liée à une déshydratation extra-cellulaire","q":"Quel est l'objectif principal du traitement de l'insuffisance rénale aiguë (IRA) fonctionnelle liée à une déshydratation extracellulaire (DEC) ?","a":"<p>L'objectif principal est de <strong>restaurer la volémie</strong> afin de rétablir une perfusion rénale adéquate, ce qui permet la réversibilité de l'IRA fonctionnelle.</p>"},{"i":"3c3cd857cdad","n":348,"o":"348-17","u":"Prise en charge","t":"Connaître la prise en charge d'une IRA fonctionnelle liée à une déshydratation extra-cellulaire","q":"Comment doit-on surveiller l'efficacité du traitement d'une IRA fonctionnelle liée à une déshydratation extracellulaire ?","a":"<p>La surveillance doit inclure :</p><ul><li>La <strong>reprise de la diurèse</strong>, qui est le 1<sup>er</sup> signe favorable (attendue en quelques heures).</li><li>La <strong>courbe de poids</strong>.</li><li>La <strong>fréquence cardiaque (FC)</strong> et la <strong>pression artérielle (PA)</strong>.</li><li>L'<strong>ionogramme urinaire</strong> pour observer la disparition des signes d'hyperaldostéronisme secondaire.</li></ul><p>La remontée de la diurèse dans les heures suivant le remplissage confirme le caractère fonctionnel de l'IRA.</p>"},{"i":"dbecec524a43","n":348,"o":"348-17","u":"Prise en charge","t":"Connaître la prise en charge d'une IRA fonctionnelle liée à une déshydratation extra-cellulaire","q":"Quels sont les facteurs iatrogènes ou diététiques à arrêter en urgence devant une IRA fonctionnelle ?","a":"<p>Il faut arrêter les facteurs aggravants tels que :</p><ul><li>Les <strong>diurétiques</strong>.</li><li>Les <strong>AINS</strong> (anti-inflammatoires non stéroïdiens).</li><li>Les <strong>antihypertenseurs</strong>.</li><li>Le <strong>régime sans sel</strong>.</li></ul>"},{"i":"dd37235a23e4","n":348,"o":"348-17","u":"Prise en charge","t":"Connaître la prise en charge d'une IRA fonctionnelle liée à une déshydratation extra-cellulaire","q":"Comment doit-on corriger la déshydratation extracellulaire (DEC) dans le cadre d'une IRA fonctionnelle ?","a":"<p>La correction de la DEC se fait par :</p><ul><li>Un <strong>apport sodé</strong> : sel de table ou gélules de <strong>NaCl per os</strong>.</li><li>L'administration de <strong>cristalloïdes (NaCl isotonique) IV</strong>.</li></ul>"},{"i":"3693f96eecf8","n":348,"o":"348-21","u":"Suivi et/ou pronostic","t":"Savoir qu'un épisode d'IRA parenchymateux expose à une insuffisance rénale chronique à long terme et nécessite un suivi","q":"Quel est le pronostic habituel de la nécrose tubulaire aiguë (NTA) spécifiquement, et quelle est la conséquence rénale potentielle à long terme ?","a":"<p>Le pronostic de la NTA est habituellement bon, avec un retour typique à l'état antérieur de la fonction rénale après <strong>1 à 3 semaines</strong> par régénération de l'épithélium tubulaire. Cependant, une <strong>séquelle (IRC) reste possible</strong>, le niveau de fonction rénale antérieure conditionnant le pronostic.</p>"},{"i":"3929179a222c","n":348,"o":"348-21","u":"Suivi et/ou pronostic","t":"Savoir qu'un épisode d'IRA parenchymateux expose à une insuffisance rénale chronique à long terme et nécessite un suivi","q":"Quelle est la principale conséquence à long terme d'un épisode d'insuffisance rénale aiguë (IRA) parenchymateuse, même résolutif ?","a":"<p>Un épisode d'IRA parenchymateuse, même résolutif, est un <strong>facteur de risque d'insuffisance rénale chronique (IRC)</strong> secondaire, pouvant évoluer vers l'insuffisance rénale terminale.</p>"},{"i":"7fa2b8181056","n":348,"o":"348-21","u":"Suivi et/ou pronostic","t":"Savoir qu'un épisode d'IRA parenchymateux expose à une insuffisance rénale chronique à long terme et nécessite un suivi","q":"Pourquoi est-il crucial de mettre en place un suivi après un épisode d'IRA parenchymateuse ?","a":"<p>Le suivi est indispensable car le <strong>risque d'IRC séquellaire persiste</strong> après la phase aiguë, et la fonction rénale doit être surveillée au cours des mois et années suivant l'épisode d'IRA.</p>"},{"i":"0ac746534b88","n":348,"o":"348-4","u":"Examens complémentaires","t":"Connaître les modalités de prescription et d'interprétation des résultats des examens complémentaires utiles au diagnostic d'IRA","q":"Quelles sont les principales indications de la ponction-biopsie rénale (PBR) dans le cadre d'une insuffisance rénale aiguë (IRA) ?","a":"<p>Les indications de la PBR sont :</p><ul><li>Un tableau de <strong>nécrose tubulaire aiguë (NTA) sans circonstances évidentes</strong>.</li><li>Des signes évoquant une <strong>néphropathie glomérulaire, vasculaire ou interstitielle</strong>.</li><li>Une fonction rénale qui <strong>ne s'améliore pas 3-4 semaines après le début</strong> de l'IRA.</li></ul>"},{"i":"4e77e1f7eb5c","n":348,"o":"348-4","u":"Examens complémentaires","t":"Connaître les modalités de prescription et d'interprétation des résultats des examens complémentaires utiles au diagnostic d'IRA","q":"Quels sont les éléments cliniques et biologiques qui orientent vers une insuffisance rénale aiguë (IRA) d'origine glomérulaire ?","a":"<ul><li>Une <strong>protéinurie &gt; 1 g/j</strong>.</li><li>Une <strong>hématurie</strong> (avec présence de GR déformés ou de cylindres).</li><li>Une <strong>HTA</strong>.</li><li>Des <strong>œdèmes</strong>.</li></ul>"},{"i":"6a44994cf28b","n":348,"o":"348-4","u":"Examens complémentaires","t":"Connaître les modalités de prescription et d'interprétation des résultats des examens complémentaires utiles au diagnostic d'IRA","q":"Quelles sont les valeurs clés des indices urinaires permettant de distinguer une IRA fonctionnelle d'une nécrose tubulaire aiguë (NTA) ?","a":"<ul><li>Le rapport urée/créatinine plasmatique est <strong>&gt; 100</strong> en cas d'IRA fonctionnelle et <strong>&lt; 50</strong> en cas de NTA.</li><li>Le Na⁺ urinaire est <strong>&lt; 20 mmol/L</strong> en cas d'IRA fonctionnelle (si pas de diurétiques) et <strong>&gt; 40 mmol/L</strong> en cas de NTA.</li><li>La Fraction d'Excrétion du Na⁺ (FE Na⁺) est <strong>&lt; 1 %</strong> en cas d'IRA fonctionnelle et <strong>&gt; 1-2 %</strong> en cas de NTA.</li><li>La Fraction d'Excrétion de l'urée (FE urée) est <strong>&lt; 35 %</strong> en cas d'IRA fonctionnelle et <strong>&gt; 35-40 %</strong> en cas de NTA.</li></ul>"},{"i":"d32b55c87486","n":348,"o":"348-4","u":"Examens complémentaires","t":"Connaître les modalités de prescription et d'interprétation des résultats des examens complémentaires utiles au diagnostic d'IRA","q":"Dans quel contexte la Fraction d'Excrétion de l'urée (FE urée) est-elle plus utile que la Fraction d'Excrétion du Na⁺ (FE Na⁺) pour diagnostiquer une insuffisance rénale aiguë (IRA) fonctionnelle versus une nécrose tubulaire aiguë (NTA) ?","a":"<p>La <strong>FE urée</strong> est plus utile que la FE Na⁺ pour faire la distinction en cas de <strong>prise de diurétiques</strong> par le patient ou de <strong>perte rénale de Na⁺</strong>, situations qui faussent l'interprétation de la FE Na⁺.</p>"},{"i":"df826c83c2bb","n":348,"o":"348-4","u":"Examens complémentaires","t":"Connaître les modalités de prescription et d'interprétation des résultats des examens complémentaires utiles au diagnostic d'IRA","q":"Quelle est la première étape de la démarche diagnostique face à une insuffisance rénale aiguë (IRA) ?","a":"<p>La première étape est d'<strong>éliminer les indications de dialyse en urgence</strong>.</p>"},{"i":"efb17566699e","n":348,"o":"348-4","u":"Examens complémentaires","t":"Connaître les modalités de prescription et d'interprétation des résultats des examens complémentaires utiles au diagnostic d'IRA","q":"Quel examen complémentaire doit être réalisé en priorité pour écarter une cause obstructive à une insuffisance rénale aiguë (IRA) ?","a":"<p>Une <strong>échographie de l'appareil urinaire</strong> doit être réalisée en priorité pour écarter un obstacle.</p>"},{"i":"12d0ad17298e","n":348,"o":"348-6","u":"Étiologies","t":"Connaître les principales étiologies d'IRA par obstacle","q":"Quelles sont les étiologies d'insuffisance rénale aiguë obstructive (IRA par obstacle) à prédominance lithiasique ?","a":"<p>Les étiologies lithiasiques sont plus fréquentes chez le <strong>sujet jeune</strong>, principalement les <strong>lithiases oxalo-calciques</strong>. Elles entraînent une IRA surtout en cas de <strong>rein unique</strong>, la migration bilatérale étant exceptionnelle.</p>"},{"i":"8bc796ab4fbc","n":348,"o":"348-6","u":"Étiologies","t":"Connaître les principales étiologies d'IRA par obstacle","q":"Quelles sont les principales causes d'insuffisance rénale aiguë obstructive (IRA par obstacle) sous-vésicales/intra-vésicales ?","a":"<ul><li><strong>Adénome de prostate</strong>, <strong>cancer de prostate</strong>, prostatite</li><li>Maladie du col vésical</li><li>Sténose de l'urètre, <strong>phimosis serré</strong></li><li><strong>Valves de l'urètre postérieur</strong> (chez l'enfant)</li><li>Vessie neurologique</li><li><strong>Caillotage</strong>, <strong>tumeur de vessie</strong>, calcul vésical</li><li>Prolapsus ou tumeur pelvienne (chez la femme)</li></ul>"},{"i":"8ceeae58fe5f","n":348,"o":"348-6","u":"Étiologies","t":"Connaître les principales étiologies d'IRA par obstacle","q":"Quelle est la condition essentielle pour qu'un obstacle provoque une insuffisance rénale aiguë (IRA) ?","a":"<p>Pour entraîner une IRA, l'obstacle doit être <strong>bilatéral</strong> ou concerner un <strong>rein unique</strong> (anatomique ou fonctionnel).</p>"},{"i":"bad0aa9e1ac4","n":348,"o":"348-6","u":"Étiologies","t":"Connaître les principales étiologies d'IRA par obstacle","q":"Quelles sont les causes uretérales intraluminales d'insuffisance rénale aiguë (IRA par obstacle) ?","a":"<ul><li><strong>Lithiase urinaire</strong></li><li><strong>Nécrose papillaire aiguë</strong></li></ul>"},{"i":"ccf3ff93ccf7","n":348,"o":"348-6","u":"Étiologies","t":"Connaître les principales étiologies d'IRA par obstacle","q":"Quelles sont les étiologies uretérales extrapariétales d'insuffisance rénale aiguë (IRA par obstacle) ?","a":"<ul><li><strong>Tumeur pelvienne localement avancée</strong> (prostate, col utérin, rectum, ovaire)</li><li><strong>Fibrose/liposclérose rétropéritonéale</strong></li><li><strong>Adénopathies lombo-aortiques</strong></li><li>Métastases rétropéritonéales</li></ul>"},{"i":"f5705692d96d","n":348,"o":"348-6","u":"Étiologies","t":"Connaître les principales étiologies d'IRA par obstacle","q":"Quelles étiologies uretérales pariétales peuvent provoquer une insuffisance rénale aiguë (IRA par obstacle) ?","a":"<ul><li><strong>Tumeur urothéliale</strong></li><li><strong>Tuberculose urogénitale</strong></li><li><strong>Sténose radique</strong></li><li>Endométriose</li><li><strong>Syndrome de la jonction pyélo-urétérale</strong></li></ul>"},{"i":"371ec7fa73d7","n":348,"o":"348-7","u":"Étiologies","t":"Connaître les principales étiologies d'IRA fonctionnelle","q":"Quels sont les facteurs de risque qui majorent le risque d'IRA fonctionnelle médicamenteuse (IEC/ARA2 ou AINS) ?","a":"<p>Le risque est majoré en cas de <strong>déshydratation</strong> ou de <strong>sténose des artères rénales</strong>.</p>"},{"i":"3d66ad603175","n":348,"o":"348-7","u":"Étiologies","t":"Connaître les principales étiologies d'IRA fonctionnelle","q":"Quels sont les médicaments pouvant induire une IRA fonctionnelle par un mécanisme hémodynamique ?","a":"<ul><li><strong>Anti-calcineurines</strong></li><li><strong>IEC</strong> (Inhibiteurs de l'Enzyme de Conversion) et <strong>ARA2</strong> (Antagonistes des Récepteurs de l'Angiotensine II), qui provoquent une vasodilatation de l'artériole efférente.</li><li><strong>AINS</strong> (Anti-Inflammatoires Non Stéroïdiens), qui induisent une vasoconstriction de l'artériole afférente.</li><li><strong>Diurétiques</strong>, surtout en cas d'hypovolémie.</li></ul>"},{"i":"4c48a81b0aaa","n":348,"o":"348-7","u":"Étiologies","t":"Connaître les principales étiologies d'IRA fonctionnelle","q":"Quelles sont les principales étiologies de l'IRA fonctionnelle liées à une hypovolémie efficace ?","a":"<ul><li><strong>Insuffisance cardiaque</strong></li><li><strong>Insuffisance hépatique</strong> (notamment cirrhose)</li><li><strong>Sepsis</strong></li></ul>"},{"i":"57b35def7c91","n":348,"o":"348-7","u":"Étiologies","t":"Connaître les principales étiologies d'IRA fonctionnelle","q":"Quelles sont les conséquences clinico-biologiques typiques de l'IRA fonctionnelle ?","a":"<ul><li><strong>Oligurie</strong></li><li><strong>Urée plasmatique augmentée > créatinine</strong> (due à une réabsorption passive accrue de l'urée)</li><li><strong>Urines pauvres en Na⁺, riches en K⁺, acides et concentrées</strong> (en rapport avec un hyperaldostéronisme secondaire)</li></ul>"},{"i":"5805d6ab1eec","n":348,"o":"348-7","u":"Étiologies","t":"Connaître les principales étiologies d'IRA fonctionnelle","q":"Quelles sont les principales étiologies de l'IRA fonctionnelle liées à une hypovolémie vraie ?","a":"<ul><li><strong>Hémorragie</strong></li><li><strong>Déshydratation extra-cellulaire</strong> (pertes digestives, rénales, cutanées)</li></ul>"},{"i":"c09cd95e4bee","n":348,"o":"348-7","u":"Étiologies","t":"Connaître les principales étiologies d'IRA fonctionnelle","q":"Quelle est la définition physiopathologique de l'insuffisance rénale aiguë (IRA) fonctionnelle ?","a":"<p>L'IRA fonctionnelle est caractérisée par une <strong>hypoperfusion rénale</strong>, c'est-à-dire une baisse du débit plasmatique rénal (DPR) et de la pression capillaire glomérulaire (Pcg), sans altération intrinsèque du parenchyme rénal. Elle est potentiellement réversible si la perfusion est rétablie.</p>"}]};